SELECT jsonb_build_object('relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'relation',to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'],
'columns',(SELECT jsonb_agg(jsonb_build_object('attribute',to_jsonb(at),'type',format_type(at.atttypid,at.atttypmod),'default',(SELECT pg_get_expr(d.adbin,d.adrelid)FROM pg_attrdef d WHERE d.adrelid=at.attrelid AND d.adnum=at.attnum))ORDER BY at.attnum)FROM pg_attribute at WHERE at.attrelid=c.oid AND at.attnum>0),
'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(k)||jsonb_build_object('definition',pg_get_constraintdef(k.oid,true))ORDER BY k.oid),'[]'::jsonb)FROM pg_constraint k WHERE k.conrelid=c.oid),
'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('catalog',to_jsonb(i),'definition',pg_get_indexdef(i.indexrelid),'relation',to_jsonb(ix)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'])ORDER BY i.indexrelid),'[]'::jsonb)FROM pg_index i JOIN pg_class ix ON ix.oid=i.indexrelid WHERE i.indrelid=c.oid AND ix.relname<>'accounting_cash_receipts_scope_time_keys'),
 'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('definition',pg_get_triggerdef(t.oid))ORDER BY t.oid),'[]'::jsonb)FROM pg_trigger t WHERE t.tgrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(pol)ORDER BY pol.oid),'[]'::jsonb)FROM pg_policy pol WHERE pol.polrelid=c.oid))ORDER BY c.oid DESC)FROM pg_class c WHERE c.oid IN('public.accounting_cash_source_work'::regclass,'public.accounting_cash_source_receipts'::regclass)),
'owners',(SELECT jsonb_agg(jsonb_build_object('definition',pg_get_functiondef(fp.oid),'metadata',to_jsonb(fp))ORDER BY fp.oid)FROM pg_proc fp WHERE fp.oid IN(SELECT (e->'metadata'->>'oid')::oid FROM jsonb_array_elements(expected->'owners')e)),
'collation',(SELECT to_jsonb(co)FROM pg_collation co WHERE co.oid=100),
'database',(SELECT to_jsonb(db)-ARRAY['oid','datacl','datdba','datname','datminmxid','datallowconn','datconnlimit','datfrozenxid','datistemplate','dattablespace','dathasloginevt']FROM pg_database db WHERE db.datname=current_database()))INTO actual;IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'cash_refusal_schema_authority_changed';END IF;END$cash_authority$;
DO $cash_owner$DECLARE p pg_proc%ROWTYPE;BEGIN SELECT*INTO STRICT p FROM pg_proc WHERE oid=to_regprocedure('fn_cash_source_refusals_for_period(uuid,uuid,timestamp with time zone,timestamp with time zone)');IF pg_get_functiondef(p.oid)IS DISTINCT FROM $cash_def$CREATE OR REPLACE FUNCTION public.fn_cash_source_refusals_for_period(p_union_id uuid, p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE problems jsonb;
BEGIN
 IF (p_union_id IS NULL)=(p_club_id IS NULL) OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from)
  OR NOT isfinite(p_to) OR p_to<=p_from THEN RAISE EXCEPTION 'invalid_cash_refusal_scope' USING ERRCODE='22023'; END IF;
 -- Read only the receipt's compact indexed identity, scope and time before
 -- fetching its reason. MATERIALIZED keeps the final detail fetch outside
 -- the global blocked queue walk; no status, scope or period test is omitted.
 WITH blocked_work AS MATERIALIZED (SELECT receipt_id FROM public.accounting_cash_source_work WHERE status='blocked'), scoped_refusals AS MATERIALIZED (
SELECT x.id FROM blocked_work w JOIN public.accounting_cash_source_receipts x ON x.id=w.receipt_id WHERE (CASE WHEN x.scope->>'kind'='unknown' THEN 'unknown' WHEN x.scope->>'kind' IN ('club','union') AND octet_length(x.scope->>'id')=36 THEN (x.scope->>'kind')||':'||(x.scope->>'id') END)=ANY(ARRAY['unknown','union:'||p_union_id::text,'club:'||p_club_id::text]) AND isfinite(x.earned_at) AND x.earned_at>=p_from AND x.earned_at<p_to
UNION ALL
SELECT x.id FROM blocked_work w JOIN public.accounting_cash_source_receipts x ON x.id=w.receipt_id WHERE (CASE WHEN x.scope->>'kind'='unknown' THEN 'unknown' WHEN x.scope->>'kind' IN ('club','union') AND octet_length(x.scope->>'id')=36 THEN (x.scope->>'kind')||':'||(x.scope->>'id') END)=ANY(ARRAY['unknown','union:'||p_union_id::text,'club:'||p_club_id::text]) AND x.earned_at=ANY(ARRAY['-infinity','infinity']::timestamptz[])
)
SELECT COALESCE(jsonb_agg(jsonb_build_object('rake_record_id',r.rake_record_id,'reason',r.reason,'scope',r.scope)
 ORDER BY r.rake_record_id),'[]'::jsonb) INTO problems
FROM scoped_refusals s JOIN public.accounting_cash_source_receipts r ON r.id=s.id;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(problems)=0 THEN 'ready' ELSE 'blocked' END,
  'count',jsonb_array_length(problems),'sources',problems);
