E 'blocked' END,\n  'count',jsonb_array_length(problems),'sources',problems);\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_cash_source_refusals_for_period","prorows":0,"pronargs":4,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_union_id","p_club_id","p_from","p_to"],"proargtypes":["2950","2950","1184","1184"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}$cash_meta$::jsonb THEN RAISE EXCEPTION 'cash_refusal_owner_changed';END IF;END$cash_owner$;
