:1,"prokind":"f","prolang":"12","proname":"RI_FKey_noaction_del","prorows":0,"pronargs":0,"proowner":"10","proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":true,"proparallel":"s","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"11","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"\"RI_FKey_noaction_upd\"()","definition":"CREATE OR REPLACE FUNCTION pg_catalog.\"RI_FKey_noaction_upd\"()\n RETURNS trigger\n LANGUAGE internal\n PARALLEL SAFE STRICT\nAS $function$RI_FKey_noaction_upd$function$\n","metadata":{"oid":"1655","proacl":null,"probin":null,"prosrc":"RI_FKey_noaction_upd","procost":1,"prokind":"f","prolang":"12","proname":"RI_FKey_noaction_upd","prorows":0,"pronargs":0,"proowner":"10","proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":true,"proparallel":"s","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"11","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_award_vip_points_from_rake()","definition":"CREATE OR REPLACE FUNCTION public.fn_award_vip_points_from_rake()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  RETURN NEW;\nEND;\n$function$\n","metadata":{"oid":"9733839","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nBEGIN\n  RETURN NEW;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_award_vip_points_from_rake","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"trg_ca_reporting_rake_insert()","definition":"CREATE OR REPLACE FUNCTION public.trg_ca_reporting_rake_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE v_day date; r record; v_fee numeric;\nBEGIN\n  IF NEW.tournament_id IS NULL AND NOT COALESCE(NEW.is_tournament, false)\n     AND NEW.table_id IS NOT NULL AND COALESCE(NEW.rake_amount, 0) > 0 THEN\n    /* 2026-10-15: the live writer for cash. SHARED lock, like every other\n       reporting trigger; only range rebuilds take it exclusive. */\n    PERFORM pg_advisory_xact_lock_shared(918273645);\n    PERFORM public.fn_ca_club_table_daily_add_rake(NEW.table_id, NEW.rake_amount, NEW.created_at, NEW.player_contributions);\n    RETURN NULL;\n  END IF;\n  IF NOT NEW.is_tournament OR NEW.tournament_id IS NULL OR NEW.rake_amount=0\n    THEN RETURN NULL; END IF;\n  /* SHARED, not exclusive - see trg_ca_reporting_wallet_insert and\n     20260906152215. */\n  PERFORM pg_advisory_xact_lock_shared(918273645);\n  v_day:=(NEW.created_at AT TIME ZONE 'UTC')::date;\n  IF NEW.metadata ? 'user_id' THEN\n    FOR r IN\n      /* 20261017204111: the named player's entry club (one club). */\n      SELECT x.club_id FROM (\n        SELECT public.fn_ca_tournament_reporting_club(NEW.tournament_id,(NEW.metadata->>'user_id')::uuid,NULL,NULL,NULL) AS club_id\n         WHERE (NEW.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') x\n       WHERE x.club_id IS NOT NULL\n    LOOP\n      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount);\n      IF v_fee=0 THEN CONTINUE; END IF;\n      INSERT INTO public.ca_club_tournament_daily AS d\n        (club_id,tournament_id,stat_date,fee,updated_at)\n      VALUES(r.club_id,NEW.tournament_id,v_day,v_fee,now())\n      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE\n       SET fee=d.fee+EXCLUDED.fee,updated_at=now();\n    END LOOP;\n  ELSE\n    FOR r IN\n      WITH total AS (SELECT count(*)::numeric n FROM public.tournament_players\n                      WHERE tournament_id=NEW.tournament_id), mapped AS (\n        /* 20261017204111: each entry under its own club, once. */\n        SELECT public.fn_ca_tournament_reporting_club(tp.tournament_id,tp.user_id,NULL,NULL,NULL) AS club_id\n          FROM public.tournament_players tp\n         WHERE tp.tournament_id=NEW.tournament_id)\n      SELECT m.club_id,count(*)::numeric AS club_players,t.n AS total_players\n        FROM mapped m CROSS JOIN total t WHERE m.club_id IS NOT NULL GROUP BY m.club_id,t.n\n       ORDER BY m.club_id\n    LOOP\n      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount*r.club_players/NULLIF(r.total_players,0));\n      IF v_fee=0 THEN CONTINUE; END IF;\n      INSERT INTO public.ca_club_tournament_daily AS d\n        (club_id,tournament_id,stat_date,fee,updated_at)\n      VALUES(r.club_id,NEW.tournament_id,v_day,\n             v_fee,now())\n      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE\n       SET fee=d.fee+EXCLUDED.fee,updated_at=now();\n    END LOOP;\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'Club Data rake rollup failed for row %: %',NEW.id,SQLERRM;\n  RETURN NULL;\nEND;\n$function$\n","metadata":{"oid":"17997342","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE v_day date; r record; v_fee numeric;\nBEGIN\n  IF NEW.tournament_id IS NULL AND NOT COALESCE(NEW.is_tournament, false)\n     AND NEW.table_id IS NOT NULL AND COALESCE(NEW.rake_amount, 0) > 0 THEN\n    /* 2026-10-15: the live writer for cash. SHARED lock, like every other\n       reporting trigger; only range rebuilds take it exclusive. */\n    PERFORM pg_advisory_xact_lock_shared(918273645);\n    PERFORM public.fn_ca_club_table_daily_add_rake(NEW.table_id, NEW.rake_amount, NEW.created_at, NEW.player_contributions);\n    RETURN NULL;\n  END IF;\n  IF NOT NEW.is_tournament OR NEW.tournament_id IS NULL OR NEW.rake_amount=0\n    THEN RETURN NULL; END IF;\n  /* SHARED, not exclusive - see trg_ca_reporting_wallet_insert and\n     20260906152215. */\n  PERFORM pg_advisory_xact_lock_shared(918273645);\n  v_day:=(NEW.created_at AT TIME ZONE 'UTC')::date;\n  IF NEW.metadata ? 'user_id' THEN\n    FOR r IN\n      /* 20261017204111: the named player's entry club (one club). */\n      SELECT x.club_id FROM (\n        SELECT public.fn_ca_tournament_reporting_club(NEW.tournament_id,(NEW.metadata->>'user_id')::uuid,NULL,NULL,NULL) AS club_id\n         WHERE (NEW.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') x\n       WHERE x.club_id IS NOT NULL\n    LOOP\n      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount);\n      IF v_fee=0 THEN CONTINUE; END IF;\n      INSERT INTO public.ca_club_tournament_daily AS d\n        (club_id,tournament_id,stat_date,fee,updated_at)\n      VALUES(r.club_id,NEW.tournament_id,v_day,v_fee,now())\n      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE\n       SET fee=d.fee+EXCLUDED.fee,updated_at=now();\n    END LOOP;\n  ELSE\n    FOR r IN\n      WITH total AS (SELECT count(*)::numeric n FROM public.tournament_players\n                      WHERE tournament_id=NEW.tournament_id), mapped AS (\n        /* 20261017204111: each entry under its own club, once. */\n        SELECT public.fn_ca_tournament_reporting_club(tp.tournament_id,tp.user_id,NULL,NULL,NULL) AS club_id\n          FROM public.tournament_players tp\n         WHERE tp.tournament_id=NEW.tournament_id)\n      SELECT m.club_id,count(*)::numeric AS club_players,t.n AS total_players\n        FROM mapped m CROSS JOIN total t WHERE m.club_id IS NOT NULL GROUP BY m.club_id,t.n\n       ORDER BY m.club_id\n    LOOP\n      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount*r.club_players/NULLIF(r.total_players,0));\n      IF v_fee=0 THEN CONTINUE; END IF;\n      INSERT INTO public.ca_club_tournament_daily AS d\n        (club_id,tournament_id,stat_date,fee,updated_at)\n      VALUES(r.club_id,NEW.tournament_id,v_day,\n             v_fee,now())\n      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE\n       SET fee=d.fee+EXCLUDED.fee,updated_at=now();\n    END LOOP;\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'Club Data rake rollup failed for row %: %',NEW.id,SQLERRM;\n  RETURN NULL;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"trg_ca_reporting_rake_insert","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_guard_watchlist()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_guard_watchlist()\n RETURNS text[]\n LANGUAGE sql\n STABLE\nAS $function$\n  SELECT ARRAY(\n    SELECT DISTINCT x FROM unnest(ARRAY[\n      'fn_ca_raise_drift_incident','fn_ca_incident_notify','fn_ca_incident_action',\n      'fn_ca_incident_escalation_tick','fn_ca_incident_recipient_ids',\n      'fn_ca_quick_reconcile','fn_ca_supply_snapshot','fn_ca_diamond_snapshot',\n      'fn_ca_suspense_regression_check','fn_ca_settlement_correctness_check',\n      'fn_ca_autoledger','fn_ca_autoledger_delete','fn_ca_chip_ledger_enrich',\n      'fn_ca_journal_append_only','fn_ca_is_midway_scope',\n      'fn_ca_negative_balance_watch','fn_ca_mint_velocity_watch',\n      'fn_ca_cron_failure_watch','fn_ca_burnin_gate_tick','fn_ca_midway_burnin_gate',\n      'fn_ca_epoch3_preflight','fn_ca_execute_epoch3_reset',\n      'fn_club_members_ledger_writer','fn_ca_financial_alert_to_incident',\n      'fn_ca_settlement_transition_guard','fn_ca_guard_defs_watch',\n      'fn_ca_post_correction','fn_ca_repair_write_failure',\n      -- The Diamond money doors (2026-09-12).\n      'fn_poker_diamond_reserve','fn_poker_diamond_release',\n      'fn_poker_diamond_cashout','fn_poker_diamond_settle_cash_hand',\n      'fn_poker_diamond_buyin','fn_poker_diamond_top_up',\n      'fn_poker_diamond_seat_keeps_custody','fn_poker_diamond_plain_cash_table',\n      -- The unit rules (2026-09-12).\n      'fn_ca_unit_floor_cents','fn_ca_tournament_unit_cents',\n      'fn_ca_prize_ladder','fn_ca_recovery_fee_cents',\n      -- The seat guards that know a tournament seat (2026-09-13).\n      'fn_poker_guard_chip_seat','fn_poker_bind_diamond_seat',\n      'fn_poker_diamond_entry_custody_is_the_entry',\n      -- The Diamond tournament money doors (Phase 8, 2026-09-14): an entry\n      -- into custody, an add to it, its refund, its unregistration and\n      -- cancellation, the drain, the prize, the fee, the close, the shadow.\n      'fn_poker_diamond_tournament_charge','fn_poker_diamond_tournament_custody_add',\n      'fn_poker_diamond_tournament_refund','fn_poker_diamond_tournament_unregister',\n      'fn_poker_diamond_tournament_cancel','fn_poker_diamond_tournament_drain',\n      'fn_poker_diamond_tournament_pay','fn_poker_diamond_tournament_settle_fee',\n      'fn_poker_diamond_tournament_close_custody','fn_poker_diamond_tournament_open_shadow',\n      -- The two guards Phase 8 taught new names, and the two chip readers it\n      -- routes by asset. The wallet guard is the one thing between a browser\n      -- and profiles.diamonds.\n      'fn_guard_profile_privileged_columns','fn_poker_guard_arena_structure',\n      'fn_ca_escrow_can_pay','fn_ca_tournament_escrow',\n      -- The Diamond satellite seat door (Phase 9, 2026-09-21): a satellite\n      -- seat moved custody to custody, out of one prize bank into an entry.\n      'fn_poker_diamond_tournament_seat_transfer',\n      -- A balance never moves without its ledger row (2026-10-01): the tally,\n      -- its two sides, the account key and the commit-time check.\n      'fn_ca_ledger_tally_add','fn_ca_ledger_tally_key','fn_ca_felt_counts_table',\n      'fn_ca_tally_balance_move','fn_ca_tally_ledger_leg','fn_ca_balance_has_its_ledger_row',\n      -- Every chip store balances with its ledger row (2026-10-02): the store\n      -- side of the tally, its pair helper and the Diamond-event scope.\n      'fn_ca_tally_store_move','fn_ca_tally_pair','fn_ca_tournament_counts',\n      -- And the list itself.\n      'fn_ca_guard_watchlist'\n    ]) x)\n$function$\n","metadata":{"oid":"18305276","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\n  SELECT ARRAY(\n    SELECT DISTINCT x FROM unnest(ARRAY[\n      'fn_ca_raise_drift_incident','fn_ca_incident_notify','fn_ca_incident_action',\n      'fn_ca_incident_escalation_tick','fn_ca_incident_recipient_ids',\n      'fn_ca_quick_reconcile','fn_ca_supply_snapshot','fn_ca_diamond_snapshot',\n      'fn_ca_suspense_regression_check','fn_ca_settlement_correctness_check',\n      'fn_ca_autoledger','fn_ca_autoledger_delete','fn_ca_chip_ledger_enrich',\n      'fn_ca_journal_append_only','fn_ca_is_midway_scope',\n      'fn_ca_negative_balance_watch','fn_ca_mint_velocity_watch',\n      'fn_ca_cron_failure_watch','fn_ca_burnin_gate_tick','fn_ca_midway_burnin_gate',\n      'fn_ca_epoch3_preflight','fn_ca_execute_epoch3_reset',\n      'fn_club_members_ledger_writer','fn_ca_financial_alert_to_incident',\n      'fn_ca_settlement_transition_guard','fn_ca_guard_defs_watch',\n      'fn_ca_post_correction','fn_ca_repair_write_failure',\n      -- The Diamond money doors (2026-09-12).\n      'fn_poker_diamond_reserve','fn_poker_diamond_release',\n      'fn_poker_diamond_cashout','fn_poker_diamond_settle_cash_hand',\n      'fn_poker_diamond_buyin','fn_poker_diamond_top_up',\n      'fn_poker_diamond_seat_keeps_custody','fn_poker_diamond_plain_cash_table',\n      -- The unit rules (2026-09-12).\n      'fn_ca_unit_floor_cents','fn_ca_tournament_unit_cents',\n      'fn_ca_prize_ladder','fn_ca_recovery_fee_cents',\n      -- The seat guards that know a tournament seat (2026-09-13).\n      'fn_poker_guard_chip_seat','fn_poker_bind_diamond_seat',\n      'fn_poker_diamond_entry_custody_is_the_entry',\n      -- The Diamond tournament money doors (Phase 8, 2026-09-14): an entry\n      -- into custody, an add to it, its refund, its unregistration and\n      -- cancellation, the drain, the prize, the fee, the close, the shadow.\n      'fn_poker_diamond_tournament_charge','fn_poker_diamond_tournament_custody_add',\n      'fn_poker_diamond_tournament_refund','fn_poker_diamond_tournament_unregister',\n      'fn_poker_diamond_tournament_cancel','fn_poker_diamond_tournament_drain',\n      'fn_poker_diamond_tournament_pay','fn_poker_diamond_tournament_settle_fee',\n      'fn_poker_diamond_tournament_close_custody','fn_poker_diamond_tournament_open_shadow',\n      -- The two guards Phase 8 taught new names, and the two chip readers it\n      -- routes by asset. The wallet guard is the one thing between a browser\n      -- and profiles.diamonds.\n      'fn_guard_profile_privileged_columns','fn_poker_guard_arena_structure',\n      'fn_ca_escrow_can_pay','fn_ca_tournament_escrow',\n      -- The Diamond satellite seat door (Phase 9, 2026-09-21): a satellite\n      -- seat moved custody to custody, out of one prize bank into an entry.\n      'fn_poker_diamond_tournament_seat_transfer',\n      -- A balance never moves without its ledger row (2026-10-01): the tally,\n      -- its two sides, the account key and the commit-time check.\n      'fn_ca_ledger_tally_add','fn_ca_ledger_tally_key','fn_ca_felt_counts_table',\n      'fn_ca_tally_balance_move','fn_ca_tally_ledger_leg','fn_ca_balance_has_its_ledger_row',\n      -- Every chip store balances with its ledger row (2026-10-02): the store\n      -- side of the tally, its pair helper and the Diamond-event scope.\n      'fn_ca_tally_store_move','fn_ca_tally_pair','fn_ca_tournament_counts',\n      -- And the list itself.\n      'fn_ca_guard_watchlist'\n    ]) x)\n","procost":100,"prokind":"f","prolang":"14","proname":"fn_ca_guard_watchlist","prorows":0,"pronargs":0,"proowner":"16384","proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"1009","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_guard_defs_watch()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_guard_defs_watch()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_name text; v_hash text; v_stored text; v_changes int := 0;\n  v_def text; v_old_id bigint; v_new_id bigint; v_declared text;\nBEGIN\n  FOREACH v_name IN ARRAY public.fn_ca_guard_watchlist()\n  LOOP\n    SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),\n           string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)\n      INTO v_hash, v_def\n      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n     WHERE n.nspname = 'public' AND p.proname = v_name;\n\n    IF v_hash IS NULL THEN\n      PERFORM public.fn_ca_raise_drift_incident(\n        'fn_ca_guard_defs_watch', 'unknown', 'warning',\n        'guard-def-missing:' || v_name,\n        0, NULL, NULL, 'reporting', 'pg_proc',\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        'guard function ' || v_name || ' no longer exists - an alarm was deleted',\n        true, jsonb_build_object('guard', v_name));\n      v_changes := v_changes + 1;\n      CONTINUE;\n    END IF;\n\n    -- Keep the text, always, so a later notice has something to diff against.\n    INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)\n    VALUES (v_name, v_hash, v_def)\n    ON CONFLICT (proname, def_hash) DO NOTHING;\n\n    SELECT def_hash INTO v_stored FROM public.ca_guard_defs WHERE proname = v_name;\n\n    -- A DECLARED INSTALL IS NOT A REVIEW NOTICE (2026-10-15). An installed\n    -- migration whose \"-- @live-proof:\" line pins this exact postimage md5 is\n    -- the redefinition's review record: it was written, reviewed and\n    -- installed on purpose. Raising an open notice for it put a row in front\n    -- of the alert fleet for every declared install (fn_ca_raise_drift_incident,\n    -- 2026-10-15 17:25 UTC, migration 20261015024752). Only the @live-proof\n    -- line counts, because it names the END state; a migration that merely\n    -- mentions a hash (a pinned preimage it moved away from) declares nothing.\n    -- A redefinition no installed migration declares is still a notice.\n    v_declared := NULL;\n    IF v_stored IS NOT NULL AND v_stored <> v_hash THEN\n      SELECT m.version INTO v_declared\n        FROM supabase_migrations.schema_migrations m\n       WHERE EXISTS (\n               SELECT 1 FROM unnest(m.statements) s\n                WHERE strpos(s, v_hash) > 0\n                  AND EXISTS (SELECT 1 FROM regexp_split_to_table(s, E'\\n') ln\n                               WHERE ln LIKE '-- @live-proof:%'\n                                 AND strpos(ln, v_hash) > 0))\n       ORDER BY m.version DESC\n       LIMIT 1;\n    END IF;\n    IF v_stored IS NULL THEN\n      INSERT INTO public.ca_guard_defs (proname, def_hash) VALUES (v_name, v_hash)\n      ON CONFLICT (proname) DO NOTHING;\n    ELSIF v_declared IS NOT NULL THEN\n      -- Declared: the baseline moves, naming the migration that declared it\n      -- (as fn_ca_declare_guard_redefinition would have), an older open\n      -- notice for this guard is superseded, and no new notice is raised.\n      UPDATE public.ca_drift_incidents\n         SET status = 'resolved', resolved_at = now(),\n             resolution = 'superseded: ' || v_name || ' was redefined by declared migration ' || v_declared\n       WHERE source = 'fn_ca_guard_defs_watch'\n         AND status <> 'resolved'\n         AND dedupe_key LIKE 'guard-def-drift:' || v_name || ':%';\n      UPDATE public.ca_guard_defs\n         SET def_hash = v_hash, updated_at = now(),\n             declared_ref = 'migration ' || v_declared || ' (@live-proof)', declared_at = now()\n       WHERE proname = v_name;\n    ELSIF v_stored <> v_hash THEN\n      v_changes := v_changes + 1;\n\n      SELECT id INTO v_old_id FROM public.ca_guard_def_history\n       WHERE proname = v_name AND def_hash = v_stored;\n      SELECT id INTO v_new_id FROM public.ca_guard_def_history\n       WHERE proname = v_name AND def_hash = v_hash;\n\n      /* A newer notice for the same guard supersedes the older one: the\n         key carries the new hash, so an old notice can never be matched\n         again and would sit open forever. */\n      UPDATE public.ca_drift_incidents\n         SET status = 'resolved', resolved_at = now(),\n             resolution = 'superseded: ' || v_name || ' was redefined again, and the newer notice carries the current definition'\n       WHERE source = 'fn_ca_guard_defs_watch'\n         AND status <> 'resolved'\n         AND dedupe_key LIKE 'guard-def-drift:' || v_name || ':%';\n\n      PERFORM public.fn_ca_raise_drift_incident(\n        'fn_ca_guard_defs_watch', 'unknown', 'info',\n        'guard-def-drift:' || v_name || ':' || left(v_hash, 12),\n        0, NULL, NULL, 'reporting', 'pg_proc',\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        'guard function ' || v_name || ' was redefined since its last baseline. '\n          || CASE WHEN v_old_id IS NULL\n                  THEN 'The previous text was never captured (it changed before this watcher kept history), so review the current definition on its own.'\n                  ELSE 'Diff it: select def_text from ca_guard_def_history where id in ('\n                       || v_old_id || ',' || v_new_id || ')'\n             END\n          || ' Then resolve this notice - it does not close itself.',\n        true, jsonb_build_object('guard', v_name, 'old_hash', v_stored, 'new_hash', v_hash,\n                                 'old_history_id', v_old_id, 'new_history_id', v_new_id));\n      UPDATE public.ca_guard_defs\n         SET def_hash = v_hash, updated_at = now() WHERE proname = v_name;\n    END IF;\n  END LOOP;\n  RETURN v_changes;\nEND $function$\n","metadata":{"oid":"18305277","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_name text; v_hash text; v_stored text; v_changes int := 0;\n  v_def text; v_old_id bigint; v_new_id bigint; v_declared text;\nBEGIN\n  FOREACH v_name IN ARRAY public.fn_ca_guard_watchlist()\n  LOOP\n    SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),\n           string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)\n      INTO v_hash, v_def\n      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n     WHERE n.nspname = 'public' AND p.proname = v_name;\n\n    IF v_hash IS NULL THEN\n      PERFORM public.fn_ca_raise_drift_incident(\n        'fn_ca_guard_defs_watch', 'unknown', 'warning',\n        'guard-def-missing:' || v_name,\n        0, NULL, NULL, 'reporting', 'pg_proc',\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        'guard function ' || v_name || ' no longer exists - an alarm was deleted',\n        true, jsonb_build_object('guard', v_name));\n      v_changes := v_changes + 1;\n      CONTINUE;\n    END IF;\n\n    -- Keep the text, always, so a later notice has something to diff against.\n    INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)\n    VALUES (v_name, v_hash, v_def)\n    ON CONFLICT (proname, def_hash) DO NOTHING;\n\n    SELECT def_hash INTO v_stored FROM public.ca_guard_defs WHERE proname = v_name;\n\n    -- A DECLARED INSTALL IS NOT A REVIEW NOTICE (2026-10-15). An installed\n    -- migration whose \"-- @live-proof:\" line pins this exact postimage md5 is\n    -- the redefinition's review record: it was written, reviewed and\n    -- installed on purpose. Raising an open notice for it put a row in front\n    -- of the alert fleet for every declared install (fn_ca_raise_drift_incident,\n    -- 2026-10-15 17:25 UTC, migration 20261015024752). Only the @live-proof\n    -- line counts, because it names the END state; a migration that merely\n    -- mentions a hash (a pinned preimage it moved away from) declares nothing.\n    -- A redefinition no installed migration declares is still a notice.\n    v_declared := NULL;\n    IF v_stored IS NOT NULL AND v_stored <> v_hash THEN\n      SELECT m.version INTO v_declared\n        FROM supabase_migrations.schema_migrations m\n       WHERE EXISTS (\n               SELECT 1 FROM unnest(m.statements) s\n                WHERE strpos(s, v_hash) > 0\n                  AND EXISTS (SELECT 1 FROM regexp_split_to_table(s, E'\\n') ln\n                               WHERE ln LIKE '-- @live-proof:%'\n                                 AND strpos(ln, v_hash) > 0))\n       ORDER BY m.version DESC\n       LIMIT 1;\n    END IF;\n    IF v_stored IS NULL THEN\n      INSERT INTO public.ca_guard_defs (proname, def_hash) VALUES (v_name, v_hash)\n      ON CONFLICT (proname) DO NOTHING;\n    ELSIF v_declared IS NOT NULL THEN\n      -- Declared: the baseline moves, naming the migration that declared it\n      -- (as fn_ca_declare_guard_redefinition would have), an older open\n      -- notice for this guard is superseded, and no new notice is raised.\n      UPDATE public.ca_drift_incidents\n         SET status = 'resolved', resolved_at = now(),\n             resolution = 'superseded: ' || v_name || ' was redefined by declared migration ' || v_declared\n       WHERE source = 'fn_ca_guard_defs_watch'\n         AND status <> 'resolved'\n         AND dedupe_key LIKE 'guard-def-drift:' || v_name || ':%';\n      UPDATE public.ca_guard_defs\n         SET def_hash = v_hash, updated_at = now(),\n             declared_ref = 'migration ' || v_declared || ' (@live-proof)', declared_at = now()\n       WHERE proname = v_name;\n    ELSIF v_stored <> v_hash THEN\n      v_changes := v_changes + 1;\n\n      SELECT id INTO v_old_id FROM public.ca_guard_def_history\n       WHERE proname = v_name AND def_hash = v_stored;\n      SELECT id INTO v_new_id FROM public.ca_guard_def_history\n       WHERE proname = v_name AND def_hash = v_hash;\n\n      /* A newer notice for the same guard supersedes the older one: the\n         key carries the new hash, so an old notice can never be matched\n         again and would sit open forever. */\n      UPDATE public.ca_drift_incidents\n         SET status = 'resolved', resolved_at = now(),\n             resolution = 'superseded: ' || v_name || ' was redefined again, and the newer notice carries the current definition'\n       WHERE source = 'fn_ca_guard_defs_watch'\n         AND status <> 'resolved'\n         AND dedupe_key LIKE 'guard-def-drift:' || v_name || ':%';\n\n      PERFORM public.fn_ca_raise_drift_incident(\n        'fn_ca_guard_defs_watch', 'unknown', 'info',\n        'guard-def-drift:' || v_name || ':' || left(v_hash, 12),\n        0, NULL, NULL, 'reporting', 'pg_proc',\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        'guard function ' || v_name || ' was redefined since its last baseline. '\n          || CASE WHEN v_old_id IS NULL\n                  THEN 'The previous text was never captured (it changed before this watcher kept history), so review the current definition on its own.'\n                  ELSE 'Diff it: select def_text from ca_guard_def_history where id in ('\n                       || v_old_id || ',' || v_new_id || ')'\n             END\n          || ' Then resolve this notice - it does not close itself.',\n        true, jsonb_build_object('guard', v_name, 'old_hash', v_stored, 'new_hash', v_hash,\n                                 'old_history_id', v_old_id, 'new_history_id', v_new_id));\n      UPDATE public.ca_guard_defs\n         SET def_hash = v_hash, updated_at = now() WHERE proname = v_name;\n    END IF;\n  END LOOP;\n  RETURN v_changes;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_guard_defs_watch","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"23","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_guard_rake_belongs_to_club()","definition":"CREATE OR REPLACE FUNCTION public.fn_guard_rake_belongs_to_club()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_owner       uuid;   -- the club/union that owns the table or tournament\n  v_owner_union uuid;   -- if the owner is a club in a union, that union\n  v_is_union    boolean;\nBEGIN\n  IF NEW.club_id IS NULL THEN\n    RETURN NEW;  -- a null club_id cannot enter another club's ledger\n  END IF;\n\n  IF NEW.table_id IS NOT NULL THEN\n    SELECT club_id INTO v_owner FROM public.tables WHERE id = NEW.table_id;\n    IF v_owner IS NULL THEN\n      RAISE EXCEPTION 'rake references table % which does not exist', NEW.table_id\n        USING ERRCODE = 'check_violation';\n    END IF;\n  ELSIF NEW.tournament_id IS NOT NULL THEN\n    SELECT club_id INTO v_owner FROM public.tournaments WHERE id = NEW.tournament_id;\n    IF v_owner IS NULL THEN\n      RETURN NEW;  -- clubless tournament: nothing to scope against\n    END IF;\n  ELSE\n    RETURN NEW;    -- neither table nor tournament: nothing to check\n  END IF;\n\n  -- The fast path: rake attributed to the owning entity itself.\n  IF NEW.club_id = v_owner THEN\n    RETURN NEW;\n  END IF;\n\n  -- Is the owner a UNION? Then member clubs may earn from its shared table.\n  SELECT EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_owner) INTO v_is_union;\n  IF v_is_union THEN\n    IF EXISTS (\n      SELECT 1 FROM public.clubs c\n       WHERE c.id = NEW.club_id\n         AND (c.union_id = v_owner\n              OR EXISTS (SELECT 1 FROM public.union_clubs uc\n                          WHERE uc.club_id = c.id AND uc.union_id = v_owner))\n    ) THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION\n      'rake club isolation: club_id % is not a member of union % that owns this game',\n      NEW.club_id, v_owner USING ERRCODE = 'check_violation';\n  END IF;\n\n  -- The owner is a CLUB. It may still legitimately attribute to a SIBLING in\n  -- its own union (a union whose shared table is recorded under the hosting\n  -- club rather than the union id). But NEVER outside that union - and a\n  -- STANDALONE club (union_id NULL) has no siblings at all, so its ledger is\n  -- sealed to itself.\n  SELECT union_id INTO v_owner_union FROM public.clubs WHERE id = v_owner;\n  IF v_owner_union IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.clubs c\n     WHERE c.id = NEW.club_id\n       AND (c.union_id = v_owner_union OR c.id = v_owner_union\n            OR EXISTS (SELECT 1 FROM public.union_clubs uc\n                        WHERE uc.club_id = c.id AND uc.union_id = v_owner_union))\n  ) THEN\n    RETURN NEW;\n  END IF;\n\n  RAISE EXCEPTION\n    'rake club isolation: club_id % may not receive rake from a game owned by club % (no shared union)',\n    NEW.club_id, v_owner USING ERRCODE = 'check_violation';\nEND;\n$function$\n","metadata":{"oid":"18772982","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_owner       uuid;   -- the club/union that owns the table or tournament\n  v_owner_union uuid;   -- if the owner is a club in a union, that union\n  v_is_union    boolean;\nBEGIN\n  IF NEW.club_id IS NULL THEN\n    RETURN NEW;  -- a null club_id cannot enter another club's ledger\n  END IF;\n\n  IF NEW.table_id IS NOT NULL THEN\n    SELECT club_id INTO v_owner FROM public.tables WHERE id = NEW.table_id;\n    IF v_owner IS NULL THEN\n      RAISE EXCEPTION 'rake references table % which does not exist', NEW.table_id\n        USING ERRCODE = 'check_violation';\n    END IF;\n  ELSIF NEW.tournament_id IS NOT NULL THEN\n    SELECT club_id INTO v_owner FROM public.tournaments WHERE id = NEW.tournament_id;\n    IF v_owner IS NULL THEN\n      RETURN NEW;  -- clubless tournament: nothing to scope against\n    END IF;\n  ELSE\n    RETURN NEW;    -- neither table nor tournament: nothing to check\n  END IF;\n\n  -- The fast path: rake attributed to the owning entity itself.\n  IF NEW.club_id = v_owner THEN\n    RETURN NEW;\n  END IF;\n\n  -- Is the owner a UNION? Then member clubs may earn from its shared table.\n  SELECT EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_owner) INTO v_is_union;\n  IF v_is_union THEN\n    IF EXISTS (\n      SELECT 1 FROM public.clubs c\n       WHERE c.id = NEW.club_id\n         AND (c.union_id = v_owner\n              OR EXISTS (SELECT 1 FROM public.union_clubs uc\n                          WHERE uc.club_id = c.id AND uc.union_id = v_owner))\n    ) THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION\n      'rake club isolation: club_id % is not a member of union % that owns this game',\n      NEW.club_id, v_owner USING ERRCODE = 'check_violation';\n  END IF;\n\n  -- The owner is a CLUB. It may still legitimately attribute to a SIBLING in\n  -- its own union (a union whose shared table is recorded under the hosting\n  -- club rather than the union id). But NEVER outside that union - and a\n  -- STANDALONE club (union_id NULL) has no siblings at all, so its ledger is\n  -- sealed to itself.\n  SELECT union_id INTO v_owner_union FROM public.clubs WHERE id = v_owner;\n  IF v_owner_union IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.clubs c\n     WHERE c.id = NEW.club_id\n       AND (c.union_id = v_owner_union OR c.id = v_owner_union\n            OR EXISTS (SELECT 1 FROM public.union_clubs uc\n                        WHERE uc.club_id = c.id AND uc.union_id = v_owner_union))\n  ) THEN\n    RETURN NEW;\n  END IF;\n\n  RAISE EXCEPTION\n    'rake club isolation: club_id % may not receive rake from a game owned by club % (no shared union)',\n    NEW.club_id, v_owner USING ERRCODE = 'check_violation';\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_guard_rake_belongs_to_club","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":false,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"trg_ca_club_rake_daily_insert()","definition":"CREATE OR REPLACE FUNCTION public.trg_ca_club_rake_daily_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE v_ids uuid[];\nBEGIN\n  SELECT array_agg(n.id) INTO v_ids\n    FROM new_rows n\n   WHERE NOT coalesce(n.is_tournament, false) AND n.club_id IS NOT NULL;\n  IF v_ids IS NOT NULL THEN\n    -- Applied at COMMIT, one row at a time, by the deferred trigger on\n    -- this scratch table: the club's day row is no longer held for the\n    -- rest of the hand (20261001005431).\n    INSERT INTO smarter_private.ca_club_rake_daily_at_commit (rake_record_id)\n    SELECT unnest(v_ids);\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'ca_club_rake_daily insert rollup failed: %', SQLERRM;\n  RETURN NULL;\nEND;\n$function$\n","metadata":{"oid":"20927883","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE v_ids uuid[];\nBEGIN\n  SELECT array_agg(n.id) INTO v_ids\n    FROM new_rows n\n   WHERE NOT coalesce(n.is_tournament, false) AND n.club_id IS NOT NULL;\n  IF v_ids IS NOT NULL THEN\n    -- Applied at COMMIT, one row at a time, by the deferred trigger on\n    -- this scratch table: the club's day row is no longer held for the\n    -- rest of the hand (20261001005431).\n    INSERT INTO smarter_private.ca_club_rake_daily_at_commit (rake_record_id)\n    SELECT unnest(v_ids);\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'ca_club_rake_daily insert rollup failed: %', SQLERRM;\n  RETURN NULL;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"trg_ca_club_rake_daily_insert","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"trg_ca_club_rake_daily_change()","definition":"CREATE OR REPLACE FUNCTION public.trg_ca_club_rake_daily_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE v_lo date; v_hi date;\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    -- Transition tables cannot be combined with a column list, so the\n    -- trigger fires on every UPDATE and the filter is here. A hand_id relink\n    -- or a metadata touch names no day.\n    SELECT min(x.d), max(x.d) INTO v_lo, v_hi\n      FROM (\n        SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o JOIN new_rows n ON n.id = o.id\n         WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n            OR o.bbj_contribution IS DISTINCT FROM n.bbj_contribution\n            OR o.pot_size IS DISTINCT FROM n.pot_size\n            OR o.created_at IS DISTINCT FROM n.created_at\n            OR o.club_id IS DISTINCT FROM n.club_id\n            OR o.table_id IS DISTINCT FROM n.table_id\n            OR o.is_tournament IS DISTINCT FROM n.is_tournament\n            OR o.player_contributions IS DISTINCT FROM n.player_contributions\n        UNION ALL\n        SELECT (n.created_at AT TIME ZONE 'UTC')::date\n          FROM old_rows o JOIN new_rows n ON n.id = o.id\n         WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n            OR o.bbj_contribution IS DISTINCT FROM n.bbj_contribution\n            OR o.pot_size IS DISTINCT FROM n.pot_size\n            OR o.created_at IS DISTINCT FROM n.created_at\n            OR o.club_id IS DISTINCT FROM n.club_id\n            OR o.table_id IS DISTINCT FROM n.table_id\n            OR o.is_tournament IS DISTINCT FROM n.is_tournament\n            OR o.player_contributions IS DISTINCT FROM n.player_contributions\n      ) x;\n  ELSE\n    SELECT min((o.created_at AT TIME ZONE 'UTC')::date), max((o.created_at AT TIME ZONE 'UTC')::date)\n      INTO v_lo, v_hi\n      FROM old_rows o;\n  END IF;\n  IF v_lo IS NOT NULL THEN\n    -- include_today => true: somebody changed a rake row, and the rollup has\n    -- to follow it today, not tomorrow.\n    PERFORM public.fn_ca_club_rake_daily_rebuild_range(v_lo, v_hi, true);\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'ca_club_rake_daily change rollup failed: %', SQLERRM;\n  RETURN NULL;\nEND;\n$function$\n","metadata":{"oid":"20927884","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE v_lo date; v_hi date;\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    -- Transition tables cannot be combined with a column list, so the\n    -- trigger fires on every UPDATE and the filter is here. A hand_id relink\n    -- or a metadata touch names no day.\n    SELECT min(x.d), max(x.d) INTO v_lo, v_hi\n      FROM (\n        SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o JOIN new_rows n ON n.id = o.id\n         WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n            OR o.bbj_contribution IS DISTINCT FROM n.bbj_contribution\n            OR o.pot_size IS DISTINCT FROM n.pot_size\n            OR o.created_at IS DISTINCT FROM n.created_at\n            OR o.club_id IS DISTINCT FROM n.club_id\n            OR o.table_id IS DISTINCT FROM n.table_id\n            OR o.is_tournament IS DISTINCT FROM n.is_tournament\n            OR o.player_contributions IS DISTINCT FROM n.player_contributions\n        UNION ALL\n        SELECT (n.created_at AT TIME ZONE 'UTC')::date\n          FROM old_rows o JOIN new_rows n ON n.id = o.id\n         WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n            OR o.bbj_contribution IS DISTINCT FROM n.bbj_contribution\n            OR o.pot_size IS DISTINCT FROM n.pot_size\n            OR o.created_at IS DISTINCT FROM n.created_at\n            OR o.club_id IS DISTINCT FROM n.club_id\n            OR o.table_id IS DISTINCT FROM n.table_id\n            OR o.is_tournament IS DISTINCT FROM n.is_tournament\n            OR o.player_contributions IS DISTINCT FROM n.player_contributions\n      ) x;\n  ELSE\n    SELECT min((o.created_at AT TIME ZONE 'UTC')::date), max((o.created_at AT TIME ZONE 'UTC')::date)\n      INTO v_lo, v_hi\n      FROM old_rows o;\n  END IF;\n  IF v_lo IS NOT NULL THEN\n    -- include_today => true: somebody changed a rake row, and the rollup has\n    -- to follow it today, not tomorrow.\n    PERFORM public.fn_ca_club_rake_daily_rebuild_range(v_lo, v_hi, true);\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'ca_club_rake_daily change rollup failed: %', SQLERRM;\n  RETURN NULL;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"trg_ca_club_rake_daily_change","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_escrow_on_rake_record()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_escrow_on_rake_record()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_fee numeric := round(COALESCE(NEW.rake_amount,0),2);\nBEGIN\n  IF NOT COALESCE(NEW.is_tournament,false) OR NEW.tournament_id IS NULL THEN\n    RETURN NULL;\n  END IF;\n  IF v_fee < 0 AND NEW.source IN (\n       'atomic_cancel_tournament',\n       'fn_unregister_from_tournament') THEN\n    RETURN NULL;\n  END IF;\n  IF NEW.source = 'fn_award_satellite_seat' THEN\n    PERFORM public.fn_ca_escrow_apply(\n      NEW.tournament_id,'satellite seat fee',\n      p_satellite_fee_in => v_fee,\n      -- Version 2 transfer gross already excludes its fee; legacy gross does not.\n      p_satellite_in => CASE WHEN NEW.metadata->>'entry_split_version'='2'\n                            THEN 0 ELSE -v_fee END);\n  ELSE\n    PERFORM public.fn_ca_escrow_apply(\n      NEW.tournament_id,'entry fee',p_fee_entries_in => v_fee);\n  END IF;\n  RETURN NULL;\nEND;\n$function$\n","metadata":{"oid":"21012780","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_fee numeric := round(COALESCE(NEW.rake_amount,0),2);\nBEGIN\n  IF NOT COALESCE(NEW.is_tournament,false) OR NEW.tournament_id IS NULL THEN\n    RETURN NULL;\n  END IF;\n  IF v_fee < 0 AND NEW.source IN (\n       'atomic_cancel_tournament',\n       'fn_unregister_from_tournament') THEN\n    RETURN NULL;\n  END IF;\n  IF NEW.source = 'fn_award_satellite_seat' THEN\n    PERFORM public.fn_ca_escrow_apply(\n      NEW.tournament_id,'satellite seat fee',\n      p_satellite_fee_in => v_fee,\n      -- Version 2 transfer gross already excludes its fee; legacy gross does not.\n      p_satellite_in => CASE WHEN NEW.metadata->>'entry_split_version'='2'\n                            THEN 0 ELSE -v_fee END);\n  ELSE\n    PERFORM public.fn_ca_escrow_apply(\n      NEW.tournament_id,'entry fee',p_fee_entries_in => v_fee);\n  END IF;\n  RETURN NULL;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_escrow_on_rake_record","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_tournament_fee_names_its_player()","definition":"CREATE OR REPLACE FUNCTION public.fn_tournament_fee_names_its_player()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_uid text := NEW.metadata->>'user_id';\n  v_pc  jsonb;\nBEGIN\n  /* Only a tournament row that arrives with no contributions and positive\n     rake. Reversal rows (negative) and rows that already name their players\n     (spin books) pass untouched. The VALUE is a weight: the allocator splits\n     the rake equally under DEALT_EQUAL, so the amount stored is immaterial;\n     rake_amount is used so a reader sees a fee, not a pot. */\n  IF v_uid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN\n    NEW.player_contributions := jsonb_build_object(v_uid, NEW.rake_amount);\n  ELSIF NEW.tournament_id IS NOT NULL THEN\n    SELECT jsonb_object_agg(tp.user_id::text, NEW.rake_amount) INTO v_pc\n      FROM public.tournament_players tp\n     WHERE tp.tournament_id = NEW.tournament_id AND tp.user_id IS NOT NULL;\n    IF v_pc IS NOT NULL THEN\n      NEW.player_contributions := v_pc;\n    END IF;\n  END IF;\n  IF NEW.player_contributions IS NOT NULL THEN\n    NEW.rake_method := COALESCE(NEW.rake_method, 'DEALT_EQUAL');\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","metadata":{"oid":"24056893","proacl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_uid text := NEW.metadata->>'user_id';\n  v_pc  jsonb;\nBEGIN\n  /* Only a tournament row that arrives with no contributions and positive\n     rake. Reversal rows (negative) and rows that already name their players\n     (spin books) pass untouched. The VALUE is a weight: the allocator splits\n     the rake equally under DEALT_EQUAL, so the amount stored is immaterial;\n     rake_amount is used so a reader sees a fee, not a pot. */\n  IF v_uid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN\n    NEW.player_contributions := jsonb_build_object(v_uid, NEW.rake_amount);\n  ELSIF NEW.tournament_id IS NOT NULL THEN\n    SELECT jsonb_object_agg(tp.user_id::text, NEW.rake_amount) INTO v_pc\n      FROM public.tournament_players tp\n     WHERE tp.tournament_id = NEW.tournament_id AND tp.user_id IS NOT NULL;\n    IF v_pc IS NOT NULL THEN\n      NEW.player_contributions := v_pc;\n    END IF;\n  END IF;\n  IF NEW.player_contributions IS NOT NULL THEN\n    NEW.rake_method := COALESCE(NEW.rake_method, 'DEALT_EQUAL');\n  END IF;\n  RETURN NEW;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_tournament_fee_names_its_player","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_unregistration_rake_evidence_is_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_unregistration_rake_evidence_is_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  -- The one write a terminal event owes every mutable evidence row: its close\n  -- marker, NULL to the event's own ended_at, nothing else changed. Every\n  -- sibling rake guard admits exactly this (fn_ca_terminal_marker_transition_\n  -- is_exact); refusing it left an event with an unregistration fee reversal\n  -- unable ever to complete, so its winner could never be paid.\n  IF TG_OP = 'UPDATE'\n     AND NEW.terminal_closed_at IS DISTINCT FROM OLD.terminal_closed_at\n     AND public.fn_ca_terminal_marker_transition_is_exact(\n           to_jsonb(OLD), to_jsonb(NEW), OLD.tournament_id) THEN\n    RETURN NEW;\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM public.tournament_unregistration_receipts receipt\n     WHERE ARRAY[OLD.id] && receipt.fee_reversal_ids\n        OR ARRAY[OLD.id] && receipt.fee_source_rake_record_ids) THEN\n    RAISE EXCEPTION\n      'committed tournament unregistration rake evidence is immutable'\n      USING ERRCODE='55000';\n  END IF;\n  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND;\n$function$\n","metadata":{"oid":"25581581","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nBEGIN\n  -- The one write a terminal event owes every mutable evidence row: its close\n  -- marker, NULL to the event's own ended_at, nothing else changed. Every\n  -- sibling rake guard admits exactly this (fn_ca_terminal_marker_transition_\n  -- is_exact); refusing it left an event with an unregistration fee reversal\n  -- unable ever to complete, so its winner could never be paid.\n  IF TG_OP = 'UPDATE'\n     AND NEW.terminal_closed_at IS DISTINCT FROM OLD.terminal_closed_at\n     AND public.fn_ca_terminal_marker_transition_is_exact(\n           to_jsonb(OLD), to_jsonb(NEW), OLD.tournament_id) THEN\n    RETURN NEW;\n  END IF;\n  IF EXISTS (\n    SELECT 1 FROM public.tournament_unregistration_receipts receipt\n     WHERE ARRAY[OLD.id] && receipt.fee_reversal_ids\n        OR ARRAY[OLD.id] && receipt.fee_source_rake_record_ids) THEN\n    RAISE EXCEPTION\n      'committed tournament unregistration rake evidence is immutable'\n      USING ERRCODE='55000';\n  END IF;\n  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_unregistration_rake_evidence_is_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_cancelled_tournament_evidence_is_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_cancelled_tournament_evidence_is_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_old_tournament_id uuid;\n  v_new_tournament_id uuid;\n  v_tournament_id uuid;\nBEGIN\n IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;\n  IF TG_OP<>'INSERT' THEN\n    v_old_tournament_id:=NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  END IF;\n  IF TG_OP<>'DELETE' THEN\n    v_new_tournament_id:=NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;\n  END IF;\n  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN\n    RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME\n      USING ERRCODE='55000';\n  END IF;\n  v_tournament_id:=COALESCE(v_new_tournament_id,v_old_tournament_id);\n  IF v_tournament_id IS NULL THEN\n    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\n  END IF;\n  IF TG_TABLE_NAME='chip_ledger' AND TG_OP<>'INSERT' THEN\n    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'\n      USING ERRCODE='55000';\n  END IF;\n  IF TG_OP='INSERT' THEN\n    PERFORM 1 FROM public.tournaments t\n     WHERE t.id=v_tournament_id FOR KEY SHARE;\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h\n              WHERE h.tournament_id=v_tournament_id) THEN\n    RAISE EXCEPTION 'cancelled tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE='55000';\n  END IF;\n  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n$function$\n","metadata":{"oid":"25705777","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_old_tournament_id uuid;\n  v_new_tournament_id uuid;\n  v_tournament_id uuid;\nBEGIN\n IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;\n  IF TG_OP<>'INSERT' THEN\n    v_old_tournament_id:=NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  END IF;\n  IF TG_OP<>'DELETE' THEN\n    v_new_tournament_id:=NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;\n  END IF;\n  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN\n    RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME\n      USING ERRCODE='55000';\n  END IF;\n  v_tournament_id:=COALESCE(v_new_tournament_id,v_old_tournament_id);\n  IF v_tournament_id IS NULL THEN\n    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\n  END IF;\n  IF TG_TABLE_NAME='chip_ledger' AND TG_OP<>'INSERT' THEN\n    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'\n      USING ERRCODE='55000';\n  END IF;\n  IF TG_OP='INSERT' THEN\n    PERFORM 1 FROM public.tournaments t\n     WHERE t.id=v_tournament_id FOR KEY SHARE;\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h\n              WHERE h.tournament_id=v_tournament_id) THEN\n    RAISE EXCEPTION 'cancelled tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE='55000';\n  END IF;\n  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_cancelled_tournament_evidence_is_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_terminal_tournament_evidence_is_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_terminal_tournament_evidence_is_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_tournament_id uuid;\n  v_status text;\n  v_receipted boolean := false;\n  v_old_marker timestamptz;\n  v_new_marker timestamptz;\nBEGIN\n IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;\n  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;\n  IF TG_OP = 'INSERT' THEN\n    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM\n       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN\n      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME\n        USING ERRCODE = '55000';\n    END IF;\n    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  ELSE\n    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  END IF;\n\n  IF v_tournament_id IS NULL THEN\n    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n    RETURN NEW;\n  END IF;\n  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN\n    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;\n  END IF;\n  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN\n    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;\n  END IF;\n  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN\n    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN\n    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN\n    IF public.fn_ca_terminal_marker_transition_is_exact(\n         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME\n      USING ERRCODE = '55000';\n  END IF;\n  -- A journal row is durable testimony from the instant it names a\n  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent\n  -- lock; a row trigger already owns the child tuple at this point. INSERT is\n  -- the only operation that takes the root lock, which preserves the\n  -- parent-to-child order used by both terminal authorities.\n  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN\n    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'INSERT' THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_tournament_id\n     FOR SHARE;\n  ELSE\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_tournament_id;\n  END IF;\n  SELECT EXISTS (\n           SELECT 1 FROM public.tournament_terminal_settlements h\n            WHERE h.tournament_id = v_tournament_id)\n      OR EXISTS (\n           SELECT 1 FROM public.tournament_satellite_settlements h\n            WHERE h.tournament_id = v_tournament_id)\n      OR EXISTS (\n           SELECT 1 FROM public.tournament_cancellation_receipts h\n            WHERE h.tournament_id = v_tournament_id)\n    INTO v_receipted;\n  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')\n     AND (TG_OP = 'INSERT' OR v_receipted) THEN\n    RAISE EXCEPTION\n      'terminal tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND;\n$function$\n","metadata":{"oid":"25706051","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_tournament_id uuid;\n  v_status text;\n  v_receipted boolean := false;\n  v_old_marker timestamptz;\n  v_new_marker timestamptz;\nBEGIN\n IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;\n  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;\n  IF TG_OP = 'INSERT' THEN\n    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;\n  ELSIF TG_OP = 'UPDATE' THEN\n    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM\n       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN\n      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME\n        USING ERRCODE = '55000';\n    END IF;\n    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  ELSE\n    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;\n  END IF;\n\n  IF v_tournament_id IS NULL THEN\n    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n    RETURN NEW;\n  END IF;\n  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN\n    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;\n  END IF;\n  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN\n    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;\n  END IF;\n  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN\n    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN\n    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN\n    IF public.fn_ca_terminal_marker_transition_is_exact(\n         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME\n      USING ERRCODE = '55000';\n  END IF;\n  -- A journal row is durable testimony from the instant it names a\n  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent\n  -- lock; a row trigger already owns the child tuple at this point. INSERT is\n  -- the only operation that takes the root lock, which preserves the\n  -- parent-to-child order used by both terminal authorities.\n  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN\n    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'INSERT' THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_tournament_id\n     FOR SHARE;\n  ELSE\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_tournament_id;\n  END IF;\n  SELECT EXISTS (\n           SELECT 1 FROM public.tournament_terminal_settlements h\n            WHERE h.tournament_id = v_tournament_id)\n      OR EXISTS (\n           SELECT 1 FROM public.tournament_satellite_settlements h\n            WHERE h.tournament_id = v_tournament_id)\n      OR EXISTS (\n           SELECT 1 FROM public.tournament_cancellation_receipts h\n            WHERE h.tournament_id = v_tournament_id)\n    INTO v_receipted;\n  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')\n     AND (TG_OP = 'INSERT' OR v_receipted) THEN\n    RAISE EXCEPTION\n      'terminal tournament % has immutable % evidence',\n      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_terminal_tournament_evidence_is_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_satellite_target_rake_is_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_satellite_target_rake_is_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_old_source_id uuid;\n  v_new_source_id uuid;\n  v_text text;\n  v_old_marker timestamptz;\n  v_new_marker timestamptz;\n  v_status text;\nBEGIN\n  IF TG_OP <> 'INSERT' THEN\n    v_text := OLD.metadata->>'satellite_id';\n    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN\n      v_old_source_id := v_text::uuid;\n    END IF;\n  END IF;\n  IF TG_OP <> 'DELETE' THEN\n    v_text := NEW.metadata->>'satellite_id';\n    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN\n      v_new_source_id := v_text::uuid;\n    END IF;\n  END IF;\n  IF TG_OP = 'UPDATE'\n     AND (NEW.metadata->>'satellite_id') IS DISTINCT FROM\n         (OLD.metadata->>'satellite_id') THEN\n    RAISE EXCEPTION 'satellite target rake ownership is immutable'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;\n  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;\n  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker\n     AND public.fn_ca_terminal_marker_transition_is_exact(\n           to_jsonb(OLD),to_jsonb(NEW),OLD.tournament_id) THEN\n    RETURN NEW;\n  END IF;\n  -- A recognized satellite fee row is append-only. Refusing an already-locked\n  -- UPDATE/DELETE before any parent lookup removes the child-to-source lock\n  -- edge. INSERT locks the target first, then the source, matching the\n  -- canonical satellite authority.\n  IF TG_OP <> 'INSERT'\n     AND COALESCE(v_old_source_id,v_new_source_id) IS NOT NULL THEN\n    RAISE EXCEPTION 'satellite target rake rows are append-only'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'INSERT' AND NEW.tournament_id IS NOT NULL THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = NEW.tournament_id FOR SHARE;\n    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN\n      RAISE EXCEPTION 'terminal target tournament cannot gain satellite rake evidence'\n        USING ERRCODE = '55000';\n    END IF;\n  END IF;\n  IF TG_OP = 'INSERT' AND v_new_source_id IS NOT NULL\n     AND v_new_source_id IS DISTINCT FROM NEW.tournament_id THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_new_source_id FOR SHARE;\n    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN\n      RAISE EXCEPTION 'completed satellite target rake evidence is immutable'\n        USING ERRCODE = '55000';\n    END IF;\n  END IF;\n  IF v_new_source_id IS NOT NULL\n     AND v_new_source_id IS DISTINCT FROM v_old_source_id THEN\n    PERFORM 1 FROM public.tournaments t\n     WHERE t.id = v_new_source_id FOR SHARE;\n  END IF;\n  IF public.fn_ca_has_committed_tournament_receipt(v_old_source_id)\n     OR public.fn_ca_has_committed_tournament_receipt(v_new_source_id) THEN\n    RAISE EXCEPTION 'completed satellite target rake evidence is immutable'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND;\n$function$\n","metadata":{"oid":"25706089","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_old_source_id uuid;\n  v_new_source_id uuid;\n  v_text text;\n  v_old_marker timestamptz;\n  v_new_marker timestamptz;\n  v_status text;\nBEGIN\n  IF TG_OP <> 'INSERT' THEN\n    v_text := OLD.metadata->>'satellite_id';\n    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN\n      v_old_source_id := v_text::uuid;\n    END IF;\n  END IF;\n  IF TG_OP <> 'DELETE' THEN\n    v_text := NEW.metadata->>'satellite_id';\n    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN\n      v_new_source_id := v_text::uuid;\n    END IF;\n  END IF;\n  IF TG_OP = 'UPDATE'\n     AND (NEW.metadata->>'satellite_id') IS DISTINCT FROM\n         (OLD.metadata->>'satellite_id') THEN\n    RAISE EXCEPTION 'satellite target rake ownership is immutable'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;\n  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;\n  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker\n     AND public.fn_ca_terminal_marker_transition_is_exact(\n           to_jsonb(OLD),to_jsonb(NEW),OLD.tournament_id) THEN\n    RETURN NEW;\n  END IF;\n  -- A recognized satellite fee row is append-only. Refusing an already-locked\n  -- UPDATE/DELETE before any parent lookup removes the child-to-source lock\n  -- edge. INSERT locks the target first, then the source, matching the\n  -- canonical satellite authority.\n  IF TG_OP <> 'INSERT'\n     AND COALESCE(v_old_source_id,v_new_source_id) IS NOT NULL THEN\n    RAISE EXCEPTION 'satellite target rake rows are append-only'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'INSERT' AND NEW.tournament_id IS NOT NULL THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = NEW.tournament_id FOR SHARE;\n    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN\n      RAISE EXCEPTION 'terminal target tournament cannot gain satellite rake evidence'\n        USING ERRCODE = '55000';\n    END IF;\n  END IF;\n  IF TG_OP = 'INSERT' AND v_new_source_id IS NOT NULL\n     AND v_new_source_id IS DISTINCT FROM NEW.tournament_id THEN\n    SELECT upper(COALESCE(t.status::text,'')) INTO v_status\n      FROM public.tournaments t\n     WHERE t.id = v_new_source_id FOR SHARE;\n    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN\n      RAISE EXCEPTION 'completed satellite target rake evidence is immutable'\n        USING ERRCODE = '55000';\n    END IF;\n  END IF;\n  IF v_new_source_id IS NOT NULL\n     AND v_new_source_id IS DISTINCT FROM v_old_source_id THEN\n    PERFORM 1 FROM public.tournaments t\n     WHERE t.id = v_new_source_id FOR SHARE;\n  END IF;\n  IF public.fn_ca_has_committed_tournament_receipt(v_old_source_id)\n     OR public.fn_ca_has_committed_tournament_receipt(v_new_source_id) THEN\n    RAISE EXCEPTION 'completed satellite target rake evidence is immutable'\n      USING ERRCODE = '55000';\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;\n  RETURN NEW;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_satellite_target_rake_is_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"trg_ca_reporting_repair_changed_days()","definition":"CREATE OR REPLACE FUNCTION public.trg_ca_reporting_repair_changed_days()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  r record;\nBEGIN\n  IF TG_TABLE_NAME = 'wallet_transactions' THEN\n    IF TG_OP = 'UPDATE' THEN\n      FOR r IN\n        SELECT DISTINCT x.d FROM (\n          SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.amount IS DISTINCT FROM n.amount\n              OR o.type IS DISTINCT FROM n.type\n              OR o.category IS DISTINCT FROM n.category\n              OR o.user_id IS DISTINCT FROM n.user_id\n              OR o.table_id IS DISTINCT FROM n.table_id\n              OR o.related_entity_id IS DISTINCT FROM n.related_entity_id\n              OR o.created_at IS DISTINCT FROM n.created_at\n          UNION\n          SELECT (n.created_at AT TIME ZONE 'UTC')::date\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.created_at IS DISTINCT FROM n.created_at\n        ) x\n        ORDER BY x.d\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    ELSE\n      FOR r IN\n        SELECT DISTINCT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o ORDER BY 1\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    END IF;\n  ELSIF TG_TABLE_NAME = 'rake_records' THEN\n    IF TG_OP = 'UPDATE' THEN\n      FOR r IN\n        SELECT DISTINCT x.d FROM (\n          SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n              OR o.created_at IS DISTINCT FROM n.created_at\n              OR o.tournament_id IS DISTINCT FROM n.tournament_id\n              OR o.is_tournament IS DISTINCT FROM n.is_tournament\n              OR o.metadata IS DISTINCT FROM n.metadata\n              OR o.club_id IS DISTINCT FROM n.club_id\n          UNION\n          SELECT (n.created_at AT TIME ZONE 'UTC')::date\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.created_at IS DISTINCT FROM n.created_at\n        ) x\n        ORDER BY x.d\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    ELSE\n      FOR r IN\n        SELECT DISTINCT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o ORDER BY 1\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    END IF;\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'Club Data changed-ledger repair failed on %: %', TG_TABLE_NAME, SQLERRM;\n  RETURN NULL;\nEND;\n$function$\n","metadata":{"oid":"25742889","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  r record;\nBEGIN\n  IF TG_TABLE_NAME = 'wallet_transactions' THEN\n    IF TG_OP = 'UPDATE' THEN\n      FOR r IN\n        SELECT DISTINCT x.d FROM (\n          SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.amount IS DISTINCT FROM n.amount\n              OR o.type IS DISTINCT FROM n.type\n              OR o.category IS DISTINCT FROM n.category\n              OR o.user_id IS DISTINCT FROM n.user_id\n              OR o.table_id IS DISTINCT FROM n.table_id\n              OR o.related_entity_id IS DISTINCT FROM n.related_entity_id\n              OR o.created_at IS DISTINCT FROM n.created_at\n          UNION\n          SELECT (n.created_at AT TIME ZONE 'UTC')::date\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.created_at IS DISTINCT FROM n.created_at\n        ) x\n        ORDER BY x.d\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    ELSE\n      FOR r IN\n        SELECT DISTINCT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o ORDER BY 1\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    END IF;\n  ELSIF TG_TABLE_NAME = 'rake_records' THEN\n    IF TG_OP = 'UPDATE' THEN\n      FOR r IN\n        SELECT DISTINCT x.d FROM (\n          SELECT (o.created_at AT TIME ZONE 'UTC')::date AS d\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.rake_amount IS DISTINCT FROM n.rake_amount\n              OR o.created_at IS DISTINCT FROM n.created_at\n              OR o.tournament_id IS DISTINCT FROM n.tournament_id\n              OR o.is_tournament IS DISTINCT FROM n.is_tournament\n              OR o.metadata IS DISTINCT FROM n.metadata\n              OR o.club_id IS DISTINCT FROM n.club_id\n          UNION\n          SELECT (n.created_at AT TIME ZONE 'UTC')::date\n            FROM old_rows o JOIN new_rows n ON n.id = o.id\n           WHERE o.created_at IS DISTINCT FROM n.created_at\n        ) x\n        ORDER BY x.d\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    ELSE\n      FOR r IN\n        SELECT DISTINCT (o.created_at AT TIME ZONE 'UTC')::date AS d\n          FROM old_rows o ORDER BY 1\n      LOOP\n        PERFORM public.ca_refresh_reporting_rollups(r.d, r.d);\n      END LOOP;\n    END IF;\n  END IF;\n  RETURN NULL;\nEXCEPTION WHEN OTHERS THEN\n  RAISE WARNING 'Club Data changed-ledger repair failed on %: %', TG_TABLE_NAME, SQLERRM;\n  RETURN NULL;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"trg_ca_reporting_repair_changed_days","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_declare_guard_redefinition(text,text)","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_declare_guard_redefinition(p_proname text, p_ref text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_hash text;\n  v_def text;\nBEGIN\n  /* A DECLARED GUARD CHANGE IS RECORDED, NOT RAISED (2026-09-10).\n     Call this from a migration that deliberately redefines a watched guard,\n     in the SAME transaction as the redefinition, passing the migration name.\n     It moves the baseline to the definition this transaction just produced,\n     so fn_ca_guard_defs_watch has nothing to report. A change nobody declares\n     still moves the hash away from the baseline and still raises. */\n  IF COALESCE(btrim(p_ref), '') = '' THEN\n    RAISE EXCEPTION 'a guard redefinition must name the migration that made it';\n  END IF;\n  IF NOT (p_proname = ANY (public.fn_ca_guard_watchlist())) THEN\n    RAISE EXCEPTION 'fn_ca_declare_guard_redefinition called for %, which is not on the guard watchlist', p_proname;\n  END IF;\n\n  SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),\n         string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)\n    INTO v_hash, v_def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = 'public' AND p.proname = p_proname;\n\n  IF v_hash IS NULL THEN\n    RAISE EXCEPTION 'guard function % does not exist; a declaration cannot baseline an absent guard', p_proname;\n  END IF;\n\n  -- keep the text so any later notice still has something to diff against\n  INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)\n  VALUES (p_proname, v_hash, v_def)\n  ON CONFLICT (proname, def_hash) DO NOTHING;\n\n  INSERT INTO public.ca_guard_defs (proname, def_hash, declared_ref, declared_at)\n  VALUES (p_proname, v_hash, p_ref, now())\n  ON CONFLICT (proname) DO UPDATE\n    SET def_hash = EXCLUDED.def_hash,\n        declared_ref = EXCLUDED.declared_ref,\n        declared_at = EXCLUDED.declared_at,\n        updated_at = now();\n\n  RETURN v_hash;\nEND;\n$function$\n","metadata":{"oid":"26711881","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_hash text;\n  v_def text;\nBEGIN\n  /* A DECLARED GUARD CHANGE IS RECORDED, NOT RAISED (2026-09-10).\n     Call this from a migration that deliberately redefines a watched guard,\n     in the SAME transaction as the redefinition, passing the migration name.\n     It moves the baseline to the definition this transaction just produced,\n     so fn_ca_guard_defs_watch has nothing to report. A change nobody declares\n     still moves the hash away from the baseline and still raises. */\n  IF COALESCE(btrim(p_ref), '') = '' THEN\n    RAISE EXCEPTION 'a guard redefinition must name the migration that made it';\n  END IF;\n  IF NOT (p_proname = ANY (public.fn_ca_guard_watchlist())) THEN\n    RAISE EXCEPTION 'fn_ca_declare_guard_redefinition called for %, which is not on the guard watchlist', p_proname;\n  END IF;\n\n  SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),\n         string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)\n    INTO v_hash, v_def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n   WHERE n.nspname = 'public' AND p.proname = p_proname;\n\n  IF v_hash IS NULL THEN\n    RAISE EXCEPTION 'guard function % does not exist; a declaration cannot baseline an absent guard', p_proname;\n  END IF;\n\n  -- keep the text so any later notice still has something to diff against\n  INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)\n  VALUES (p_proname, v_hash, v_def)\n  ON CONFLICT (proname, def_hash) DO NOTHING;\n\n  INSERT INTO public.ca_guard_defs (proname, def_hash, declared_ref, declared_at)\n  VALUES (p_proname, v_hash, p_ref, now())\n  ON CONFLICT (proname) DO UPDATE\n    SET def_hash = EXCLUDED.def_hash,\n        declared_ref = EXCLUDED.declared_ref,\n        declared_at = EXCLUDED.declared_at,\n        updated_at = now();\n\n  RETURN v_hash;\nEND;\n","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_declare_guard_redefinition","prorows":0,"pronargs":2,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_proname","p_ref"],"proargtypes":["25","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_cash_source_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_cash_source_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE old_source_id uuid;new_source_id uuid;hand uuid;\nBEGIN\n IF TG_TABLE_NAME='rake_records' THEN\n  old_source_id:=OLD.id;new_source_id:=NEW.id;\n ELSE\n  IF TG_OP<>'INSERT' THEN old_source_id:=OLD.rake_record_id; END IF;\n  IF TG_OP<>'DELETE' THEN new_source_id:=NEW.rake_record_id; END IF;\n END IF;\n -- The commission writer and every source mutation share the same hand key.\n -- A source edit which began before accrual must finish before it is frozen.\n FOR hand IN SELECT DISTINCT r.hand_id FROM public.rake_records r WHERE r.id IN(old_source_id,new_source_id) AND r.hand_id IS NOT NULL ORDER BY r.hand_id LOOP\n  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||hand::text,0));\n END LOOP;\n IF EXISTS(SELECT 1 FROM public.accounting_cash_accrual_batches WHERE rake_record_id IN(old_source_id,new_source_id)) THEN\n  RAISE EXCEPTION 'recorded_cash_earning_source_is_immutable' USING ERRCODE='55000';\n END IF;\n RETURN COALESCE(NEW,OLD);\nEND $function$\n","metadata":{"oid":"34785307","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE old_source_id uuid;new_source_id uuid;hand uuid;\nBEGIN\n IF TG_TABLE_NAME='rake_records' THEN\n  old_source_id:=OLD.id;new_source_id:=NEW.id;\n ELSE\n  IF TG_OP<>'INSERT' THEN old_source_id:=OLD.rake_record_id; END IF;\n  IF TG_OP<>'DELETE' THEN new_source_id:=NEW.rake_record_id; END IF;\n END IF;\n -- The commission writer and every source mutation share the same hand key.\n -- A source edit which began before accrual must finish before it is frozen.\n FOR hand IN SELECT DISTINCT r.hand_id FROM public.rake_records r WHERE r.id IN(old_source_id,new_source_id) AND r.hand_id IS NOT NULL ORDER BY r.hand_id LOOP\n  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||hand::text,0));\n END LOOP;\n IF EXISTS(SELECT 1 FROM public.accounting_cash_accrual_batches WHERE rake_record_id IN(old_source_id,new_source_id)) THEN\n  RAISE EXCEPTION 'recorded_cash_earning_source_is_immutable' USING ERRCODE='55000';\n END IF;\n RETURN COALESCE(NEW,OLD);\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_cash_source_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_fee_fingerprint(rake_records)","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_fingerprint(p_row rake_records)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO 'public'\nAS $function$\n -- Versioned economic fields are stable across unrelated schema additions.\n -- Tuple terminal markers are not economic source edits.\n SELECT md5(jsonb_build_object('id',p_row.id,'hand_id',p_row.hand_id,'table_id',p_row.table_id,'club_id',p_row.club_id,'rake_amount',p_row.rake_amount,'bbj_contribution',p_row.bbj_contribution,'pot_size',p_row.pot_size,'num_players',p_row.num_players,'created_at',p_row.created_at,'player_contributions',p_row.player_contributions,'global_hand_id',p_row.global_hand_id,'is_tournament',p_row.is_tournament,'tournament_id',p_row.tournament_id,'source',p_row.source,'metadata',p_row.metadata,'rake_method',p_row.rake_method,'returned_uncalled',p_row.returned_uncalled)::text)\n$function$\n","metadata":{"oid":"34785501","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\n -- Versioned economic fields are stable across unrelated schema additions.\n -- Tuple terminal markers are not economic source edits.\n SELECT md5(jsonb_build_object('id',p_row.id,'hand_id',p_row.hand_id,'table_id',p_row.table_id,'club_id',p_row.club_id,'rake_amount',p_row.rake_amount,'bbj_contribution',p_row.bbj_contribution,'pot_size',p_row.pot_size,'num_players',p_row.num_players,'created_at',p_row.created_at,'player_contributions',p_row.player_contributions,'global_hand_id',p_row.global_hand_id,'is_tournament',p_row.is_tournament,'tournament_id',p_row.tournament_id,'source',p_row.source,'metadata',p_row.metadata,'rake_method',p_row.rake_method,'returned_uncalled',p_row.returned_uncalled)::text)\n","procost":100,"prokind":"f","prolang":"14","proname":"fn_accounting_tournament_fee_fingerprint","prorows":0,"pronargs":1,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_row"],"proargtypes":["123163"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_fee_commit_capture()","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_commit_capture()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$BEGIN\n PERFORM public.fn_stamp_accounting_tournament_fee(NEW.id);RETURN NULL;\nEND$function$\n","metadata":{"oid":"34785512","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"BEGIN\n PERFORM public.fn_stamp_accounting_tournament_fee(NEW.id);RETURN NULL;\nEND","procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_tournament_fee_commit_capture","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_fee_source_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_source_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$BEGIN\n IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=OLD.id)\n  AND (TG_OP='DELETE' OR public.fn_accounting_tournament_fee_fingerprint(OLD) IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(NEW)) THEN\n  RAISE EXCEPTION 'captured_tournament_fee_source_is_immutable' USING ERRCODE='55000';\n END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND$function$\n","metadata":{"oid":"34785525","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"BEGIN\n IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=OLD.id)\n  AND (TG_OP='DELETE' OR public.fn_accounting_tournament_fee_fingerprint(OLD) IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(NEW)) THEN\n  RAISE EXCEPTION 'captured_tournament_fee_source_is_immutable' USING ERRCODE='55000';\n END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND","procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_tournament_fee_source_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_recognized_evidence_immutable()","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_recognized_evidence_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$DECLARE event uuid;BEGIN\n IF TG_TABLE_NAME='rake_records' THEN\n  event:=CASE WHEN TG_OP='INSERT' THEN NEW.tournament_id ELSE OLD.tournament_id END;\n  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=event)\n   AND (TG_OP<>'UPDATE' OR public.fn_accounting_tournament_fee_fingerprint(OLD) IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(NEW)) THEN\n   RAISE EXCEPTION 'recognized_tournament_fee_evidence_is_immutable' USING ERRCODE='55000'; END IF;\n ELSE\n  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE\n   (TG_TABLE_NAME='chip_ledger' AND bank_journal_id=OLD.id) OR (TG_TABLE_NAME='union_wallet_transactions' AND union_wallet_transaction_id=OLD.id)) THEN\n   RAISE EXCEPTION 'recognized_tournament_fee_bank_receipt_is_immutable' USING ERRCODE='55000'; END IF;\n END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND$function$\n","metadata":{"oid":"34785597","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"DECLARE event uuid;BEGIN\n IF TG_TABLE_NAME='rake_records' THEN\n  event:=CASE WHEN TG_OP='INSERT' THEN NEW.tournament_id ELSE OLD.tournament_id END;\n  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=event)\n   AND (TG_OP<>'UPDATE' OR public.fn_accounting_tournament_fee_fingerprint(OLD) IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(NEW)) THEN\n   RAISE EXCEPTION 'recognized_tournament_fee_evidence_is_immutable' USING ERRCODE='55000'; END IF;\n ELSE\n  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE\n   (TG_TABLE_NAME='chip_ledger' AND bank_journal_id=OLD.id) OR (TG_TABLE_NAME='union_wallet_transactions' AND union_wallet_transaction_id=OLD.id)) THEN\n   RAISE EXCEPTION 'recognized_tournament_fee_bank_receipt_is_immutable' USING ERRCODE='55000'; END IF;\n END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND","procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_tournament_recognized_evidence_immutable","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_week_quality(uuid,timestamp with time zone,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_week_quality(p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE event record;scope_union uuid;actual_union uuid;related boolean;unknown_scope boolean;\n proof jsonb;active_ids uuid[];refunded_ids uuid[];checked int:=0;issue_count bigint;\nBEGIN\n IF p_club_id IS NULL OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to\n THEN RAISE EXCEPTION 'invalid_accounting_tournament_week' USING ERRCODE='22023';END IF;\n SELECT union_id INTO scope_union FROM public.clubs WHERE id=p_club_id;\n IF NOT FOUND THEN RAISE EXCEPTION 'accounting_club_not_found' USING ERRCODE='22023';END IF;\n FOR event IN\n  WITH candidates_all AS (\n   SELECT tournament_id FROM public.accounting_tournament_fee_recognitions WHERE recognized_at>=p_from AND recognized_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_rake_settlements WHERE settled_at>=p_from AND settled_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_terminal_settlements WHERE COALESCE(settled_at,completed_at)>=p_from AND COALESCE(settled_at,completed_at)<p_to\n   UNION SELECT tournament_id FROM public.tournament_cancellation_receipts WHERE settled_at>=p_from AND settled_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_satellite_settlements WHERE settled_at>=p_from AND settled_at<p_to\n  ), candidates AS (\n   -- A CHIP WEEK READS NO DIAMOND EVENT (2026-10-12): a Diamond Arena event's\n   -- fee is settled in Diamonds to the Diamond house and owes no chip rakeback\n   -- or commission, so it has no chip recognition and is no chip week's\n   -- business (the definition of fn_poker_diamond_tournament).\n   SELECT a.tournament_id FROM candidates_all a\n    WHERE a.tournament_id NOT IN(SELECT t.id FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id\n     WHERE c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL)\n  ), ev AS (\n   SELECT c.tournament_id,r.recognized_at,r.status,r.net_rake,r.union_id,r.bank_club_id,r.source_fingerprint,\n    b.settled_at AS bank_at,b.amount AS bank_amount,b.union_id AS bank_union,b.club_id AS fee_bank_club\n    FROM candidates c LEFT JOIN public.accounting_tournament_fee_recognitions r USING(tournament_id)\n     LEFT JOIN public.tournament_rake_settlements b ON b.tournament_id=c.tournament_id\n  ), scoped AS (\n   SELECT e.*,COALESCE(f.fee_source_count,0) AS fee_source_count,COALESCE(f.scope_count,0) AS scope_count,\n    CASE WHEN f.scope_count=1 THEN f.one_union END AS source_union,\n    COALESCE(e.union_id,e.bank_union,CASE WHEN f.scope_count=1 THEN f.one_union END) AS actual_union\n    FROM ev e LEFT JOIN LATERAL (\n     SELECT count(*) AS fee_source_count,\n      count(DISTINCT COALESCE(s.union_id::text,'private')) AS scope_count,\n      min(s.union_id::text)::uuid AS one_union\n      FROM public.accounting_tournament_fee_sources s\n      WHERE s.tournament_id=e.tournament_id GROUP BY s.tournament_id OFFSET 0\n    ) f ON true\n    -- The original's first CONTINUE: an event whose banked/recognised instant\n    -- sits outside the week, and whose recognition is outside it too, is not\n    -- this week's business at all.\n    WHERE COALESCE(e.bank_at,e.recognized_at) IS NULL\n       OR (COALESCE(e.bank_at,e.recognized_at)>=p_from AND COALESCE(e.bank_at,e.recognized_at)<p_to)\n       OR (e.recognized_at IS NOT NULL AND e.recognized_at>=p_from AND e.recognized_at<p_to)\n  ), survivors AS (\n   SELECT s.* FROM scoped s\n    WHERE COALESCE(s.actual_union=scope_union,false)\n       OR COALESCE(s.bank_club_id=p_club_id,false)\n       OR COALESCE(s.fee_bank_club=p_club_id,false)\n       OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources cs WHERE cs.tournament_id=s.tournament_id\n        AND (cs.club_id=p_club_id OR (scope_union IS NOT NULL AND cs.coordinator_union_id=scope_union)) OFFSET 0)\n       OR EXISTS(SELECT 1 FROM public.tournament_refund_entitlements cr WHERE cr.tournament_id=s.tournament_id\n        AND cr.refund_wallet_club_id=p_club_id OFFSET 0)\n       OR (s.actual_union IS NULL AND (s.status IS NULL OR s.status='banked_accrual_deferred')\n        AND (COALESCE(s.net_rake,s.bank_amount,0)>0\n         OR EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount<>0 OFFSET 0))\n        AND (NOT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount>0 OFFSET 0)\n         OR EXISTS(SELECT 1 FROM public.rake_records r LEFT JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id\n          WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount>0\n           AND ((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(r)\n            OR r.rake_amount IS DISTINCT FROM(SELECT sum(s2.rake_credit) FROM public.accounting_tournament_fee_sources s2 WHERE s2.rake_record_id=r.id)) OFFSET 0)\n         OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s3 WHERE s3.tournament_id=s.tournament_id\n          AND (NOT(s3.contract ? 'coordinator_union_id') OR s3.contract->'membership'->>'history_id' IS NULL\n           OR s3.contract->>'club_id' IS DISTINCT FROM s3.club_id::text OR s3.contract->>'player_id' IS DISTINCT FROM s3.player_id::text) OFFSET 0)))\n  ), survivor_ids AS MATERIALIZED (\n   -- A CTE scan carries no index, so joining the aggregates below to\n   -- `survivors` by tournament_id made the planner merge-join a FULL scan of\n   -- idx_rake_records_tournament. Handing them one array instead turns every\n   -- one of them into `tournament_id = ANY(p_club_id)` against the real index.\n   SELECT array_agg(k.tournament_id) AS ids FROM survivors k\n  ), rr AS MATERIALIZED (\n   SELECT r.tournament_id,r.id,r.rake_amount,r.hand_id,md5(jsonb_build_object('id',r.id,'hand_id',r.hand_id,'table_id',r.table_id,'club_id',r.club_id,'rake_amount',r.rake_amount,'bbj_contribution',r.bbj_contribution,'pot_size',r.pot_size,'num_players',r.num_players,'created_at',r.created_at,'player_contributions',r.player_contributions,'global_hand_id',r.global_hand_id,'is_tournament',r.is_tournament,'tournament_id',r.tournament_id,'source',r.source,'metadata',r.metadata,'rake_method',r.rake_method,'returned_uncalled',r.returned_uncalled)::text) AS fp\n    FROM public.rake_records r\n    WHERE r.is_tournament AND EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=r.tournament_id)\n  ), src_sum AS (\n   SELECT s.rake_record_id,sum(s.rake_credit) AS credited\n    FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM rr original_member WHERE original_member.id=s.rake_record_id) GROUP BY s.rake_record_id\n  ), rr_agg AS (\n   SELECT rr.tournament_id,\n    count(*) FILTER(WHERE rr.rake_amount IS NULL OR rr.rake_amount<>round(rr.rake_amount,2)\n      OR rr.rake_amount::text IN('NaN','Infinity','-Infinity') OR rr.hand_id IS NOT NULL) AS invalid_rows,\n    count(*) FILTER(WHERE rr.rake_amount<0) AS negative_rows,\n    COALESCE(sum(rr.rake_amount),0) AS raw_total,\n    md5(COALESCE(string_agg(rr.fp,':' ORDER BY rr.id),'')) AS fingerprint\n    FROM rr GROUP BY rr.tournament_id\n  ), batch_rows AS MATERIALIZED (\n   SELECT b.rake_record_id,b.status,b.tournament_id,b.source_fingerprint,b.rake_amount\n    FROM (SELECT DISTINCT original_member.id FROM rr original_member) original_keys CROSS JOIN LATERAL (SELECT original_batch.* FROM public.accounting_tournament_fee_batches original_batch WHERE original_batch.rake_record_id=original_keys.id OFFSET 0) b\n  ), batch_bad AS (\n   SELECT rr.tournament_id,count(*) AS bad\n    FROM rr LEFT JOIN batch_rows b ON b.rake_record_id=rr.id\n            LEFT JOIN src_sum ss ON ss.rake_record_id=rr.id\n    WHERE rr.rake_amount>0\n     AND (((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) AND NOT public.fn_accounting_mixed_cutover_spin_proof_valid(rr.id))\n      OR b.tournament_id IS DISTINCT FROM rr.tournament_id\n      OR b.source_fingerprint IS DISTINCT FROM rr.fp\n      OR b.rake_amount IS DISTINCT FROM rr.rake_amount\n      OR b.rake_amount IS DISTINCT FROM ss.credited)\n    GROUP BY rr.tournament_id\n  ), selected_event_sources AS MATERIALIZED (\n   SELECT s.* FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=s.tournament_id)\n  ), selected_event_recognized AS MATERIALIZED (\n   SELECT rs.* FROM public.accounting_tournament_recognized_sources rs\n    WHERE EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=rs.tournament_id)\n  ), selected_receipt_recognized AS MATERIALIZED (\n   -- Receipt join is by source_id, including wrong-event receipts.\n   SELECT rs.* FROM public.accounting_tournament_recognized_sources rs\n    WHERE EXISTS(SELECT 1 FROM selected_event_sources original_member WHERE original_member.id=rs.source_id)\n  ), orphan_source_identities AS MATERIALIZED (\n   -- Global source identities preserve wrong-event and missing-source semantics.\n   SELECT s.id,s.tournament_id FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM selected_event_recognized original_member WHERE original_member.source_id=s.id)\n  ), scope_bad AS (\n   SELECT s.tournament_id,count(*) AS bad\n    FROM selected_event_sources s\n    LEFT JOIN rr ON rr.id=s.rake_record_id AND rr.tournament_id=s.tournament_id AND rr.rake_amount>0\n    WHERE rr.id IS NULL GROUP BY s.tournament_id\n  ), receipt_bad AS (\n   SELECT s.tournament_id,count(*) AS bad\n    FROM selected_event_sources s JOIN survivors k ON k.tournament_id=s.tournament_id\n    LEFT JOIN selected_receipt_recognized rs ON rs.source_id=s.id\n    WHERE (rs.source_id IS NULL OR rs.tournament_id IS DISTINCT FROM s.tournament_id\n     OR rs.recognized_at IS DISTINCT FROM k.recognized_at\n     OR rs.disposition IS DISTINCT FROM 'earned'\n     OR rs.rake_credit IS DISTINCT FROM s.rake_credit\n     OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text\n     OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text\n     OR (s.contract->>'rake_credit')::numeric IS DISTINCT FROM s.rake_credit\n     OR (s.contract->>'terms_at')::timestamptz IS DISTINCT FROM public.fn_accounting_tournament_source_terms_at(s.tournament_id,s.charged_at,s.contract)\n     OR s.charged_at>k.recognized_at\n     OR NULLIF(s.contract->>'union_id','')::uuid IS DISTINCT FROM s.union_id\n     OR NULLIF(s.contract->>'coordinator_union_id','')::uuid IS DISTINCT FROM s.coordinator_union_id)\n    GROUP BY s.tournament_id\n  ), orphan_bad AS (\n   SELECT rs.tournament_id,count(*) AS bad\n    FROM selected_event_recognized rs\n    LEFT JOIN orphan_source_identities s ON s.id=rs.source_id\n    WHERE (s.id IS NULL OR s.tournament_id IS DISTINCT FROM rs.tournament_id) GROUP BY rs.tournament_id\n  ), earned_sum AS (\n   SELECT rs.tournament_id,COALESCE(sum(rs.rake_credit),0) AS earned\n    FROM selected_event_recognized rs\n    WHERE rs.disposition='earned' GROUP BY rs.tournament_id\n  ), aggregate_maps AS MATERIALIZED (\n   SELECT\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM rr_agg x) AS rr_agg_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM batch_bad x) AS batch_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM scope_bad x) AS scope_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM receipt_bad x) AS receipt_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM orphan_bad x) AS orphan_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM earned_sum x) AS earned_sum_map\n  )\n  SELECT k.tournament_id,k.recognized_at,k.status,k.net_rake,k.union_id,k.bank_club_id,k.source_fingerprint,\n   k.bank_at,k.bank_amount,k.bank_union,k.fee_bank_club,k.actual_union,k.source_union,k.scope_count,\n   COALESCE(a.invalid_rows,0) AS invalid_rows,COALESCE(a.negative_rows,0) AS negative_rows,\n   COALESCE(a.raw_total,0) AS raw_total,COALESCE(a.fingerprint,md5('')) AS fingerprint,\n   COALESCE(bb.bad,0) AS batch_bad,COALESCE(sb.bad,0) AS scope_bad,COALESCE(rb.bad,0) AS receipt_bad,\n   COALESCE(ob.bad,0) AS orphan_bad,COALESCE(es.earned,0) AS earned_sum\n   FROM survivors k CROSS JOIN aggregate_maps m\n   LEFT JOIN LATERAL jsonb_to_record(m.rr_agg_map->k.tournament_id::text) AS a(invalid_rows bigint,negative_rows bigint,raw_total numeric,fingerprint text) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.batch_bad_map->k.tournament_id::text) AS bb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.scope_bad_map->k.tournament_id::text) AS sb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.receipt_bad_map->k.tournament_id::text) AS rb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.orphan_bad_map->k.tournament_id::text) AS ob(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.earned_sum_map->k.tournament_id::text) AS es(earned numeric) ON true\n   ORDER BY k.tournament_id\n LOOP\n  actual_union:=event.actual_union;\n  checked:=checked+1;\n  -- `unknown_scope` is REPORTED, not decided, here: `survivors` above already\n  -- filters on the identical expression, so it chose the same events either\n  -- way. It is still computed VERBATIM rather than abbreviated, because the two\n  -- blocked responses below carry it to a reader, and a field that is true a\n  -- little more often than it used to be is a wrong answer however cheap it is.\n  -- It costs nothing: only an event that is about to be RETURNED reaches it,\n  -- and a RETURN ends the loop.\n  unknown_scope:=false;\n  IF event.status IS NULL OR event.status='banked_accrual_deferred' THEN\n   unknown_scope:=actual_union IS NULL\n    AND (COALESCE(event.net_rake,event.bank_amount,0)>0\n     OR EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount<>0))\n    AND (NOT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount>0)\n     OR EXISTS(SELECT 1 FROM public.rake_records r LEFT JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id\n      WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount>0\n       AND ((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(r)\n        OR r.rake_amount IS DISTINCT FROM(SELECT sum(s.rake_credit) FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id=r.id)))\n     OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s WHERE s.tournament_id=event.tournament_id\n      AND (NOT(s.contract ? 'coordinator_union_id') OR s.contract->'membership'->>'history_id' IS NULL\n       OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text)));\n  END IF;\n  IF event.status IS NULL THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_terminal_recognition_missing','tournament_id',event.tournament_id,'unknown_scope',unknown_scope);\n  END IF;\n  IF event.status='banked_accrual_deferred' THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_deferred','tournament_id',event.tournament_id,'unknown_scope',unknown_scope);\n  END IF;\n  -- An eventual normal/satellite terminal receipt may follow a banked fee in\n  -- another week. Only original fee-bank/recognition time chooses its liability.\n  IF event.bank_at IS NOT NULL AND (event.bank_at IS DISTINCT FROM event.recognized_at\n    OR event.bank_amount IS DISTINCT FROM event.net_rake OR event.bank_union IS DISTINCT FROM event.union_id) THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_bank_disagrees','tournament_id',event.tournament_id);\n  END IF;\n  IF event.negative_rows=0 AND event.invalid_rows=0 AND event.raw_total>=0\n     AND event.scope_count<=1 AND event.batch_bad=0 AND event.scope_bad=0 THEN\n   -- net_plan is determined for this event; see the note above 2.3.\n   IF event.fingerprint IS DISTINCT FROM event.source_fingerprint\n     OR event.raw_total IS DISTINCT FROM event.net_rake\n     OR event.source_union IS DISTINCT FROM event.union_id\n     OR (event.status='recognized') IS DISTINCT FROM(event.net_rake>0)\n     OR (event.status='cancelled') IS DISTINCT FROM(event.net_rake=0) THEN\n    RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_disagrees_with_sources','tournament_id',event.tournament_id);\n   END IF;\n   IF event.receipt_bad>0 OR event.orphan_bad>0 OR event.earned_sum IS DISTINCT FROM event.net_rake THEN\n    RETURN jsonb_build_object('status','blocked','reason','tournament_recognized_source_receipts_incomplete','tournament_id',event.tournament_id);\n   END IF;\n   CONTINUE;\n  END IF;\n  -- SLOW PATH, unchanged: a refund reversal, or a cheap fact that already\n  -- disagrees, still gets the full per-event proof and its exact detail.\n  BEGIN proof:=public.fn_accounting_tournament_fee_net_plan(event.tournament_id);\n  EXCEPTION WHEN SQLSTATE '23514' OR SQLSTATE '55000' THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_net_source_evidence_invalid','detail',SQLERRM,'tournament_id',event.tournament_id);\n  END;\n  IF proof->>'status' IS DISTINCT FROM 'proven' OR proof->>'source_fingerprint' IS DISTINCT FROM event.source_fingerprint\n    OR (proof->>'net_fee')::numeric IS DISTINCT FROM event.net_rake OR NULLIF(proof->>'union_id','')::uuid IS DISTINCT FROM event.union_id\n    OR (event.status='recognized') IS DISTINCT FROM(event.net_rake>0)\n    OR (event.status='cancelled') IS DISTINCT FROM(event.net_rake=0) THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_disagrees_with_sources','tournament_id',event.tournament_id);\n  END IF;\n  SELECT COALESCE(array_agg(value::uuid),'{}') INTO active_ids FROM jsonb_array_elements_text(proof->'active_source_ids');\n  SELECT COALESCE(array_agg(value::uuid),'{}') INTO refunded_ids FROM jsonb_array_elements_text(proof->'refunded_source_ids');\n  SELECT count(*) INTO issue_count FROM public.accounting_tournament_fee_sources s\n   LEFT JOIN public.accounting_tournament_recognized_sources rs ON rs.source_id=s.id\n   WHERE s.tournament_id=event.tournament_id AND (rs.source_id IS NULL OR rs.tournament_id IS DISTINCT FROM s.tournament_id\n    OR rs.recognized_at IS DISTINCT FROM event.recognized_at\n    OR NOT(s.id=ANY(active_ids||refunded_ids))\n    OR rs.disposition IS DISTINCT FROM CASE WHEN s.id=ANY(active_ids) THEN 'earned' ELSE 'refunded' END\n    OR rs.rake_credit IS DISTINCT FROM CASE WHEN s.id=ANY(active_ids) THEN s.rake_credit ELSE 0 END\n    OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text\n    OR (s.contract->>'rake_credit')::numeric IS DISTINCT FROM s.rake_credit\n    OR (s.contract->>'terms_at')::timestamptz IS DISTINCT FROM public.fn_accounting_tournament_source_terms_at(s.tournament_id,s.charged_at,s.contract) OR s.charged_at>event.recognized_at\n    OR NULLIF(s.contract->>'union_id','')::uuid IS DISTINCT FROM s.union_id\n    OR NULLIF(s.contract->>'coordinator_union_id','')::uuid IS DISTINCT FROM s.coordinator_union_id);\n  IF issue_count>0 OR EXISTS(SELECT 1 FROM public.accounting_tournament_recognized_sources rs\n   LEFT JOIN public.accounting_tournament_fee_sources s ON s.id=rs.source_id\n   WHERE rs.tournament_id=event.tournament_id AND (s.id IS NULL OR s.tournament_id IS DISTINCT FROM event.tournament_id))\n   OR (SELECT COALESCE(sum(rake_credit),0) FROM public.accounting_tournament_recognized_sources WHERE tournament_id=event.tournament_id AND disposition='earned') IS DISTINCT FROM event.net_rake THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognized_source_receipts_incomplete','tournament_id',event.tournament_id);\n  END IF;\n END LOOP;\n RETURN jsonb_build_object('status','ready','checked',checked);\nEND $function$\n","metadata":{"oid":"34785647","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE event record;scope_union uuid;actual_union uuid;related boolean;unknown_scope boolean;\n proof jsonb;active_ids uuid[];refunded_ids uuid[];checked int:=0;issue_count bigint;\nBEGIN\n IF p_club_id IS NULL OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to\n THEN RAISE EXCEPTION 'invalid_accounting_tournament_week' USING ERRCODE='22023';END IF;\n SELECT union_id INTO scope_union FROM public.clubs WHERE id=p_club_id;\n IF NOT FOUND THEN RAISE EXCEPTION 'accounting_club_not_found' USING ERRCODE='22023';END IF;\n FOR event IN\n  WITH candidates_all AS (\n   SELECT tournament_id FROM public.accounting_tournament_fee_recognitions WHERE recognized_at>=p_from AND recognized_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_rake_settlements WHERE settled_at>=p_from AND settled_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_terminal_settlements WHERE COALESCE(settled_at,completed_at)>=p_from AND COALESCE(settled_at,completed_at)<p_to\n   UNION SELECT tournament_id FROM public.tournament_cancellation_receipts WHERE settled_at>=p_from AND settled_at<p_to\n   UNION SELECT tournament_id FROM public.tournament_satellite_settlements WHERE settled_at>=p_from AND settled_at<p_to\n  ), candidates AS (\n   -- A CHIP WEEK READS NO DIAMOND EVENT (2026-10-12): a Diamond Arena event's\n   -- fee is settled in Diamonds to the Diamond house and owes no chip rakeback\n   -- or commission, so it has no chip recognition and is no chip week's\n   -- business (the definition of fn_poker_diamond_tournament).\n   SELECT a.tournament_id FROM candidates_all a\n    WHERE a.tournament_id NOT IN(SELECT t.id FROM public.tournaments t JOIN public.clubs c ON c.id=t.club_id\n     WHERE c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL AND t.union_id IS NULL)\n  ), ev AS (\n   SELECT c.tournament_id,r.recognized_at,r.status,r.net_rake,r.union_id,r.bank_club_id,r.source_fingerprint,\n    b.settled_at AS bank_at,b.amount AS bank_amount,b.union_id AS bank_union,b.club_id AS fee_bank_club\n    FROM candidates c LEFT JOIN public.accounting_tournament_fee_recognitions r USING(tournament_id)\n     LEFT JOIN public.tournament_rake_settlements b ON b.tournament_id=c.tournament_id\n  ), scoped AS (\n   SELECT e.*,COALESCE(f.fee_source_count,0) AS fee_source_count,COALESCE(f.scope_count,0) AS scope_count,\n    CASE WHEN f.scope_count=1 THEN f.one_union END AS source_union,\n    COALESCE(e.union_id,e.bank_union,CASE WHEN f.scope_count=1 THEN f.one_union END) AS actual_union\n    FROM ev e LEFT JOIN LATERAL (\n     SELECT count(*) AS fee_source_count,\n      count(DISTINCT COALESCE(s.union_id::text,'private')) AS scope_count,\n      min(s.union_id::text)::uuid AS one_union\n      FROM public.accounting_tournament_fee_sources s\n      WHERE s.tournament_id=e.tournament_id GROUP BY s.tournament_id OFFSET 0\n    ) f ON true\n    -- The original's first CONTINUE: an event whose banked/recognised instant\n    -- sits outside the week, and whose recognition is outside it too, is not\n    -- this week's business at all.\n    WHERE COALESCE(e.bank_at,e.recognized_at) IS NULL\n       OR (COALESCE(e.bank_at,e.recognized_at)>=p_from AND COALESCE(e.bank_at,e.recognized_at)<p_to)\n       OR (e.recognized_at IS NOT NULL AND e.recognized_at>=p_from AND e.recognized_at<p_to)\n  ), survivors AS (\n   SELECT s.* FROM scoped s\n    WHERE COALESCE(s.actual_union=scope_union,false)\n       OR COALESCE(s.bank_club_id=p_club_id,false)\n       OR COALESCE(s.fee_bank_club=p_club_id,false)\n       OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources cs WHERE cs.tournament_id=s.tournament_id\n        AND (cs.club_id=p_club_id OR (scope_union IS NOT NULL AND cs.coordinator_union_id=scope_union)) OFFSET 0)\n       OR EXISTS(SELECT 1 FROM public.tournament_refund_entitlements cr WHERE cr.tournament_id=s.tournament_id\n        AND cr.refund_wallet_club_id=p_club_id OFFSET 0)\n       OR (s.actual_union IS NULL AND (s.status IS NULL OR s.status='banked_accrual_deferred')\n        AND (COALESCE(s.net_rake,s.bank_amount,0)>0\n         OR EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount<>0 OFFSET 0))\n        AND (NOT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount>0 OFFSET 0)\n         OR EXISTS(SELECT 1 FROM public.rake_records r LEFT JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id\n          WHERE r.tournament_id=s.tournament_id AND r.is_tournament AND r.rake_amount>0\n           AND ((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(r)\n            OR r.rake_amount IS DISTINCT FROM(SELECT sum(s2.rake_credit) FROM public.accounting_tournament_fee_sources s2 WHERE s2.rake_record_id=r.id)) OFFSET 0)\n         OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s3 WHERE s3.tournament_id=s.tournament_id\n          AND (NOT(s3.contract ? 'coordinator_union_id') OR s3.contract->'membership'->>'history_id' IS NULL\n           OR s3.contract->>'club_id' IS DISTINCT FROM s3.club_id::text OR s3.contract->>'player_id' IS DISTINCT FROM s3.player_id::text) OFFSET 0)))\n  ), survivor_ids AS MATERIALIZED (\n   -- A CTE scan carries no index, so joining the aggregates below to\n   -- `survivors` by tournament_id made the planner merge-join a FULL scan of\n   -- idx_rake_records_tournament. Handing them one array instead turns every\n   -- one of them into `tournament_id = ANY(p_club_id)` against the real index.\n   SELECT array_agg(k.tournament_id) AS ids FROM survivors k\n  ), rr AS MATERIALIZED (\n   SELECT r.tournament_id,r.id,r.rake_amount,r.hand_id,md5(jsonb_build_object('id',r.id,'hand_id',r.hand_id,'table_id',r.table_id,'club_id',r.club_id,'rake_amount',r.rake_amount,'bbj_contribution',r.bbj_contribution,'pot_size',r.pot_size,'num_players',r.num_players,'created_at',r.created_at,'player_contributions',r.player_contributions,'global_hand_id',r.global_hand_id,'is_tournament',r.is_tournament,'tournament_id',r.tournament_id,'source',r.source,'metadata',r.metadata,'rake_method',r.rake_method,'returned_uncalled',r.returned_uncalled)::text) AS fp\n    FROM public.rake_records r\n    WHERE r.is_tournament AND EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=r.tournament_id)\n  ), src_sum AS (\n   SELECT s.rake_record_id,sum(s.rake_credit) AS credited\n    FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM rr original_member WHERE original_member.id=s.rake_record_id) GROUP BY s.rake_record_id\n  ), rr_agg AS (\n   SELECT rr.tournament_id,\n    count(*) FILTER(WHERE rr.rake_amount IS NULL OR rr.rake_amount<>round(rr.rake_amount,2)\n      OR rr.rake_amount::text IN('NaN','Infinity','-Infinity') OR rr.hand_id IS NOT NULL) AS invalid_rows,\n    count(*) FILTER(WHERE rr.rake_amount<0) AS negative_rows,\n    COALESCE(sum(rr.rake_amount),0) AS raw_total,\n    md5(COALESCE(string_agg(rr.fp,':' ORDER BY rr.id),'')) AS fingerprint\n    FROM rr GROUP BY rr.tournament_id\n  ), batch_rows AS MATERIALIZED (\n   SELECT b.rake_record_id,b.status,b.tournament_id,b.source_fingerprint,b.rake_amount\n    FROM (SELECT DISTINCT original_member.id FROM rr original_member) original_keys CROSS JOIN LATERAL (SELECT original_batch.* FROM public.accounting_tournament_fee_batches original_batch WHERE original_batch.rake_record_id=original_keys.id OFFSET 0) b\n  ), batch_bad AS (\n   SELECT rr.tournament_id,count(*) AS bad\n    FROM rr LEFT JOIN batch_rows b ON b.rake_record_id=rr.id\n            LEFT JOIN src_sum ss ON ss.rake_record_id=rr.id\n    WHERE rr.rake_amount>0\n     AND (((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) AND NOT public.fn_accounting_mixed_cutover_spin_proof_valid(rr.id))\n      OR b.tournament_id IS DISTINCT FROM rr.tournament_id\n      OR b.source_fingerprint IS DISTINCT FROM rr.fp\n      OR b.rake_amount IS DISTINCT FROM rr.rake_amount\n      OR b.rake_amount IS DISTINCT FROM ss.credited)\n    GROUP BY rr.tournament_id\n  ), selected_event_sources AS MATERIALIZED (\n   SELECT s.* FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=s.tournament_id)\n  ), selected_event_recognized AS MATERIALIZED (\n   SELECT rs.* FROM public.accounting_tournament_recognized_sources rs\n    WHERE EXISTS(SELECT 1 FROM survivors original_member WHERE original_member.tournament_id=rs.tournament_id)\n  ), selected_receipt_recognized AS MATERIALIZED (\n   -- Receipt join is by source_id, including wrong-event receipts.\n   SELECT rs.* FROM public.accounting_tournament_recognized_sources rs\n    WHERE EXISTS(SELECT 1 FROM selected_event_sources original_member WHERE original_member.id=rs.source_id)\n  ), orphan_source_identities AS MATERIALIZED (\n   -- Global source identities preserve wrong-event and missing-source semantics.\n   SELECT s.id,s.tournament_id FROM public.accounting_tournament_fee_sources s\n    WHERE EXISTS(SELECT 1 FROM selected_event_recognized original_member WHERE original_member.source_id=s.id)\n  ), scope_bad AS (\n   SELECT s.tournament_id,count(*) AS bad\n    FROM selected_event_sources s\n    LEFT JOIN rr ON rr.id=s.rake_record_id AND rr.tournament_id=s.tournament_id AND rr.rake_amount>0\n    WHERE rr.id IS NULL GROUP BY s.tournament_id\n  ), receipt_bad AS (\n   SELECT s.tournament_id,count(*) AS bad\n    FROM selected_event_sources s JOIN survivors k ON k.tournament_id=s.tournament_id\n    LEFT JOIN selected_receipt_recognized rs ON rs.source_id=s.id\n    WHERE (rs.source_id IS NULL OR rs.tournament_id IS DISTINCT FROM s.tournament_id\n     OR rs.recognized_at IS DISTINCT FROM k.recognized_at\n     OR rs.disposition IS DISTINCT FROM 'earned'\n     OR rs.rake_credit IS DISTINCT FROM s.rake_credit\n     OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text\n     OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text\n     OR (s.contract->>'rake_credit')::numeric IS DISTINCT FROM s.rake_credit\n     OR (s.contract->>'terms_at')::timestamptz IS DISTINCT FROM public.fn_accounting_tournament_source_terms_at(s.tournament_id,s.charged_at,s.contract)\n     OR s.charged_at>k.recognized_at\n     OR NULLIF(s.contract->>'union_id','')::uuid IS DISTINCT FROM s.union_id\n     OR NULLIF(s.contract->>'coordinator_union_id','')::uuid IS DISTINCT FROM s.coordinator_union_id)\n    GROUP BY s.tournament_id\n  ), orphan_bad AS (\n   SELECT rs.tournament_id,count(*) AS bad\n    FROM selected_event_recognized rs\n    LEFT JOIN orphan_source_identities s ON s.id=rs.source_id\n    WHERE (s.id IS NULL OR s.tournament_id IS DISTINCT FROM rs.tournament_id) GROUP BY rs.tournament_id\n  ), earned_sum AS (\n   SELECT rs.tournament_id,COALESCE(sum(rs.rake_credit),0) AS earned\n    FROM selected_event_recognized rs\n    WHERE rs.disposition='earned' GROUP BY rs.tournament_id\n  ), aggregate_maps AS MATERIALIZED (\n   SELECT\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM rr_agg x) AS rr_agg_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM batch_bad x) AS batch_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM scope_bad x) AS scope_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM receipt_bad x) AS receipt_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM orphan_bad x) AS orphan_bad_map,\n    (SELECT jsonb_object_agg(x.tournament_id::text,to_jsonb(x)-'tournament_id') FROM earned_sum x) AS earned_sum_map\n  )\n  SELECT k.tournament_id,k.recognized_at,k.status,k.net_rake,k.union_id,k.bank_club_id,k.source_fingerprint,\n   k.bank_at,k.bank_amount,k.bank_union,k.fee_bank_club,k.actual_union,k.source_union,k.scope_count,\n   COALESCE(a.invalid_rows,0) AS invalid_rows,COALESCE(a.negative_rows,0) AS negative_rows,\n   COALESCE(a.raw_total,0) AS raw_total,COALESCE(a.fingerprint,md5('')) AS fingerprint,\n   COALESCE(bb.bad,0) AS batch_bad,COALESCE(sb.bad,0) AS scope_bad,COALESCE(rb.bad,0) AS receipt_bad,\n   COALESCE(ob.bad,0) AS orphan_bad,COALESCE(es.earned,0) AS earned_sum\n   FROM survivors k CROSS JOIN aggregate_maps m\n   LEFT JOIN LATERAL jsonb_to_record(m.rr_agg_map->k.tournament_id::text) AS a(invalid_rows bigint,negative_rows bigint,raw_total numeric,fingerprint text) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.batch_bad_map->k.tournament_id::text) AS bb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.scope_bad_map->k.tournament_id::text) AS sb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.receipt_bad_map->k.tournament_id::text) AS rb(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.orphan_bad_map->k.tournament_id::text) AS ob(bad bigint) ON true\n   LEFT JOIN LATERAL jsonb_to_record(m.earned_sum_map->k.tournament_id::text) AS es(earned numeric) ON true\n   ORDER BY k.tournament_id\n LOOP\n  actual_union:=event.actual_union;\n  checked:=checked+1;\n  -- `unknown_scope` is REPORTED, not decided, here: `survivors` above already\n  -- filters on the identical expression, so it chose the same events either\n  -- way. It is still computed VERBATIM rather than abbreviated, because the two\n  -- blocked responses below carry it to a reader, and a field that is true a\n  -- little more often than it used to be is a wrong answer however cheap it is.\n  -- It costs nothing: only an event that is about to be RETURNED reaches it,\n  -- and a RETURN ends the loop.\n  unknown_scope:=false;\n  IF event.status IS NULL OR event.status='banked_accrual_deferred' THEN\n   unknown_scope:=actual_union IS NULL\n    AND (COALESCE(event.net_rake,event.bank_amount,0)>0\n     OR EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount<>0))\n    AND (NOT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount>0)\n     OR EXISTS(SELECT 1 FROM public.rake_records r LEFT JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id=r.id\n      WHERE r.tournament_id=event.tournament_id AND r.is_tournament AND r.rake_amount>0\n       AND ((b.status IS DISTINCT FROM 'captured' AND NOT (CASE WHEN EXISTS(SELECT 1 FROM public.accounting_owner_direct_fee_proofs original_owner_proof WHERE original_owner_proof.rake_record_id=b.rake_record_id) THEN public.fn_accounting_owner_direct_fee_proof_valid(b.rake_record_id) ELSE false END)) OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(r)\n        OR r.rake_amount IS DISTINCT FROM(SELECT sum(s.rake_credit) FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id=r.id)))\n     OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources s WHERE s.tournament_id=event.tournament_id\n      AND (NOT(s.contract ? 'coordinator_union_id') OR s.contract->'membership'->>'history_id' IS NULL\n       OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text)));\n  END IF;\n  IF event.status IS NULL THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_terminal_recognition_missing','tournament_id',event.tournament_id,'unknown_scope',unknown_scope);\n  END IF;\n  IF event.status='banked_accrual_deferred' THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_deferred','tournament_id',event.tournament_id,'unknown_scope',unknown_scope);\n  END IF;\n  -- An eventual normal/satellite terminal receipt may follow a banked fee in\n  -- another week. Only original fee-bank/recognition time chooses its liability.\n  IF event.bank_at IS NOT NULL AND (event.bank_at IS DISTINCT FROM event.recognized_at\n    OR event.bank_amount IS DISTINCT FROM event.net_rake OR event.bank_union IS DISTINCT FROM event.union_id) THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_bank_disagrees','tournament_id',event.tournament_id);\n  END IF;\n  IF event.negative_rows=0 AND event.invalid_rows=0 AND event.raw_total>=0\n     AND event.scope_count<=1 AND event.batch_bad=0 AND event.scope_bad=0 THEN\n   -- net_plan is determined for this event; see the note above 2.3.\n   IF event.fingerprint IS DISTINCT FROM event.source_fingerprint\n     OR event.raw_total IS DISTINCT FROM event.net_rake\n     OR event.source_union IS DISTINCT FROM event.union_id\n     OR (event.status='recognized') IS DISTINCT FROM(event.net_rake>0)\n     OR (event.status='cancelled') IS DISTINCT FROM(event.net_rake=0) THEN\n    RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_disagrees_with_sources','tournament_id',event.tournament_id);\n   END IF;\n   IF event.receipt_bad>0 OR event.orphan_bad>0 OR event.earned_sum IS DISTINCT FROM event.net_rake THEN\n    RETURN jsonb_build_object('status','blocked','reason','tournament_recognized_source_receipts_incomplete','tournament_id',event.tournament_id);\n   END IF;\n   CONTINUE;\n  END IF;\n  -- SLOW PATH, unchanged: a refund reversal, or a cheap fact that already\n  -- disagrees, still gets the full per-event proof and its exact detail.\n  BEGIN proof:=public.fn_accounting_tournament_fee_net_plan(event.tournament_id);\n  EXCEPTION WHEN SQLSTATE '23514' OR SQLSTATE '55000' THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_net_source_evidence_invalid','detail',SQLERRM,'tournament_id',event.tournament_id);\n  END;\n  IF proof->>'status' IS DISTINCT FROM 'proven' OR proof->>'source_fingerprint' IS DISTINCT FROM event.source_fingerprint\n    OR (proof->>'net_fee')::numeric IS DISTINCT FROM event.net_rake OR NULLIF(proof->>'union_id','')::uuid IS DISTINCT FROM event.union_id\n    OR (event.status='recognized') IS DISTINCT FROM(event.net_rake>0)\n    OR (event.status='cancelled') IS DISTINCT FROM(event.net_rake=0) THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognition_disagrees_with_sources','tournament_id',event.tournament_id);\n  END IF;\n  SELECT COALESCE(array_agg(value::uuid),'{}') INTO active_ids FROM jsonb_array_elements_text(proof->'active_source_ids');\n  SELECT COALESCE(array_agg(value::uuid),'{}') INTO refunded_ids FROM jsonb_array_elements_text(proof->'refunded_source_ids');\n  SELECT count(*) INTO issue_count FROM public.accounting_tournament_fee_sources s\n   LEFT JOIN public.accounting_tournament_recognized_sources rs ON rs.source_id=s.id\n   WHERE s.tournament_id=event.tournament_id AND (rs.source_id IS NULL OR rs.tournament_id IS DISTINCT FROM s.tournament_id\n    OR rs.recognized_at IS DISTINCT FROM event.recognized_at\n    OR NOT(s.id=ANY(active_ids||refunded_ids))\n    OR rs.disposition IS DISTINCT FROM CASE WHEN s.id=ANY(active_ids) THEN 'earned' ELSE 'refunded' END\n    OR rs.rake_credit IS DISTINCT FROM CASE WHEN s.id=ANY(active_ids) THEN s.rake_credit ELSE 0 END\n    OR s.contract->>'player_id' IS DISTINCT FROM s.player_id::text OR s.contract->>'club_id' IS DISTINCT FROM s.club_id::text\n    OR (s.contract->>'rake_credit')::numeric IS DISTINCT FROM s.rake_credit\n    OR (s.contract->>'terms_at')::timestamptz IS DISTINCT FROM public.fn_accounting_tournament_source_terms_at(s.tournament_id,s.charged_at,s.contract) OR s.charged_at>event.recognized_at\n    OR NULLIF(s.contract->>'union_id','')::uuid IS DISTINCT FROM s.union_id\n    OR NULLIF(s.contract->>'coordinator_union_id','')::uuid IS DISTINCT FROM s.coordinator_union_id);\n  IF issue_count>0 OR EXISTS(SELECT 1 FROM public.accounting_tournament_recognized_sources rs\n   LEFT JOIN public.accounting_tournament_fee_sources s ON s.id=rs.source_id\n   WHERE rs.tournament_id=event.tournament_id AND (s.id IS NULL OR s.tournament_id IS DISTINCT FROM event.tournament_id))\n   OR (SELECT COALESCE(sum(rake_credit),0) FROM public.accounting_tournament_recognized_sources WHERE tournament_id=event.tournament_id AND disposition='earned') IS DISTINCT FROM event.net_rake THEN\n   RETURN jsonb_build_object('status','blocked','reason','tournament_recognized_source_receipts_incomplete','tournament_id',event.tournament_id);\n  END IF;\n END LOOP;\n RETURN jsonb_build_object('status','ready','checked',checked);\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_tournament_week_quality","prorows":0,"pronargs":3,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_club_id","p_from","p_to"],"proargtypes":["2950","1184","1184"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_guard_mtt_admission_contract()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_guard_mtt_admission_contract()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE v_expected jsonb := $prepared${\"functions\":[{\"signature\":\"public.ca_club_tournaments(uuid,integer,integer)\",\"definition_md5\":\"4637d9ee6db98fddcd88597ed3b31411\",\"owner\":\"postgres\",\"acl\":[\"authenticated=X/postgres\",\"postgres=X/postgres\",\"service_role=X/post