XCEPTION 'MTT_ACTIVATION_MAINTENANCE_ORDER_REFUSED' USING ERRCODE='55000';\n   END IF;\n   IF current_setting('transaction_isolation')<>'read committed'\n      OR current_setting('session_replication_role')<>'origin' THEN\n    RAISE EXCEPTION 'MTT_ACTIVATION_REQUIRES_ORIGIN_READ_COMMITTED' USING ERRCODE='55000';\n   END IF;\n   IF public.fn_entry_purchases_frozen() THEN\n    RAISE EXCEPTION 'MTT_ACTIVATION_MAINTENANCE_FROZEN' USING ERRCODE='55000';\n   END IF;\n   -- No DDL, parent FOR UPDATE, or financial effects after ABI exclusion.\n   -- These are the exact final authorities produced by the eight preparation\n   -- migrations, installed L03 authoring rules and reviewed L04 cohort closure.\n   -- pg_get_functiondef includes volatility/security/configuration.\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'functions') LOOP\n    v_oid:=to_regprocedure(v_pin->>'signature');\n    SELECT jsonb_build_object('definition_md5',md5(pg_get_functiondef(p.oid)),\n      'owner',pg_get_userbyid(p.proowner),'acl',\n      (SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner)))a))\n      INTO v_actual FROM pg_proc p WHERE p.oid=v_oid;\n    IF v_actual IS DISTINCT FROM v_pin-'signature' THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_AUTHORITY_DRIFT: %',v_pin->>'signature' USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'triggers') LOOP\n    SELECT jsonb_build_array(t.tgrelid::regclass::text,t.tgname,pg_get_triggerdef(t.oid),t.tgenabled)\n      INTO v_actual FROM pg_trigger t\n      WHERE t.tgrelid=to_regclass('public.'||(v_pin->>0)) AND t.tgname=v_pin->>1;\n    IF v_actual IS DISTINCT FROM v_pin THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_TRIGGER_DRIFT: %.%',v_pin->>0,v_pin->>1 USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'constraints') LOOP\n    SELECT jsonb_build_array(x.conrelid::regclass::text,x.conname,pg_get_constraintdef(x.oid),x.convalidated)\n      INTO v_actual FROM pg_constraint x\n      WHERE x.conrelid=to_regclass('public.'||(v_pin->>0)) AND x.conname=v_pin->>1;\n    IF v_actual IS DISTINCT FROM v_pin OR EXISTS(\n      SELECT 1 FROM pg_trigger t JOIN pg_constraint x ON x.oid=t.tgconstraint\n       WHERE x.conrelid=to_regclass('public.'||(v_pin->>0)) AND x.conname=v_pin->>1\n         AND t.tgenabled<>'O') THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_CONSTRAINT_DRIFT: %.%',v_pin->>0,v_pin->>1 USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'columns') LOOP\n    SELECT jsonb_build_array(a.attrelid::regclass::text,a.attname,a.atttypid::regtype::text,\n      a.attnotnull,a.attacl,pg_get_expr(d.adbin,d.adrelid)) INTO v_actual\n      FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum\n      WHERE a.attrelid=to_regclass('public.'||(v_pin->>0)) AND a.attname=v_pin->>1 AND NOT a.attisdropped;\n    IF v_actual IS DISTINCT FROM v_pin THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_COLUMN_DRIFT: %.%',v_pin->>0,v_pin->>1 USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'indexes') LOOP\n    SELECT jsonb_build_array(i.indexrelid::regclass::text,pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready)\n      INTO v_actual FROM pg_index i WHERE i.indexrelid=to_regclass('public.'||(v_pin->>0));\n    IF v_actual IS DISTINCT FROM v_pin THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_INDEX_DRIFT: %',v_pin->>0 USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'event_triggers') LOOP\n    SELECT jsonb_build_object('name',e.evtname,'tags',e.evttags,'event',e.evtevent,\n      'owner',pg_get_userbyid(e.evtowner),'enabled',e.evtenabled,'function',e.evtfoid::regprocedure::text)\n      INTO v_actual FROM pg_event_trigger e WHERE e.evtname=v_pin->>'name';\n    IF v_actual IS DISTINCT FROM v_pin THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_EVENT_GUARD_DRIFT: %',v_pin->>'name' USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   -- Newly installed funding writers also depend on private evidence tables.\n   -- Preserve all earlier activation checks and verify the reached table graph.\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'funding_relations') LOOP\n    SELECT jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',\n      (SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(coalesce(c.relacl,acldefault('r',c.relowner)))a),\n      'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) INTO v_actual\n      FROM pg_class c WHERE c.oid=to_regclass('public.'||(v_pin->>'name'));\n    IF v_actual IS DISTINCT FROM v_pin\n      OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=to_regclass('public.'||(v_pin->>'name')))\n      OR (SELECT count(*) FROM pg_trigger WHERE tgrelid=to_regclass('public.'||(v_pin->>'name')) AND NOT tgisinternal)\n         <> (SELECT count(*) FROM jsonb_array_elements(v_expected->'triggers')x WHERE x->>0=v_pin->>'name')\n      OR (SELECT count(*) FROM pg_attribute WHERE attrelid=to_regclass('public.'||(v_pin->>'name')) AND attnum>0 AND NOT attisdropped)\n         <> (SELECT count(*) FROM jsonb_array_elements(v_expected->'funding_columns')x WHERE x->>0=v_pin->>'name') THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_FUNDING_RELATION_DRIFT: %',v_pin->>'name' USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   FOR v_pin IN SELECT value FROM jsonb_array_elements(v_expected->'funding_columns') LOOP\n    SELECT jsonb_build_array(a.attrelid::regclass::text,a.attname,a.atttypid::regtype::text,\n      a.attnotnull,a.attacl,pg_get_expr(d.adbin,d.adrelid),a.attidentity) INTO v_actual\n      FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum\n      WHERE a.attrelid=to_regclass('public.'||(v_pin->>0)) AND a.attname=v_pin->>1 AND NOT a.attisdropped;\n    IF v_actual IS DISTINCT FROM v_pin THEN\n     RAISE EXCEPTION 'MTT_ACTIVATION_FUNDING_COLUMN_DRIFT: %.%',v_pin->>0,v_pin->>1 USING ERRCODE='55000';\n    END IF;\n   END LOOP;\n   SELECT jsonb_build_object('proname',proname,'status',status,'notes',notes) INTO v_actual\n     FROM public.ca_money_rpc_registry WHERE proname='fn_ca_settle_satellite_cohort';\n   IF v_actual IS DISTINCT FROM v_expected->'cohort_registry' THEN\n    RAISE EXCEPTION 'MTT_ACTIVATION_COHORT_REGISTRY_DRIFT' USING ERRCODE='55000';\n   END IF;\n   SELECT jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',\n     (SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(coalesce(c.relacl,acldefault('r',c.relowner)))a),\n     'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) INTO v_actual\n     FROM pg_class c WHERE c.oid='public.ca_mtt_admission_contract'::regclass;\n   IF v_actual IS DISTINCT FROM '{\"owner\":\"postgres\",\"acl\":[\"postgres=arwdDxtm/postgres\"],\"rls\":true,\"force_rls\":false}'::jsonb\n      OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.ca_mtt_admission_contract'::regclass)\n      OR (SELECT count(*) FROM public.ca_mtt_admission_contract)<>1\n      OR (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.ca_mtt_admission_contract'::regclass AND NOT tgisinternal)<>2\n      OR (SELECT count(*) FROM pg_attribute WHERE attrelid='public.ca_mtt_admission_contract'::regclass AND attnum>0 AND NOT attisdropped)<>2 THEN\n    RAISE EXCEPTION 'MTT_ACTIVATION_PRIVATE_CONTRACT_DRIFT' USING ERRCODE='55000';\n   END IF;\n   -- Terminal historical rows intentionally may remain unqualified. Existing\n   -- active-parent index and exact uppercase status constraint bound this read.\n   IF EXISTS(SELECT 1 FROM public.tournaments WHERE status IN ('ANNOUNCED','REGISTERING','LATE_REG','RUNNING')\n     AND (format_contract IS NULL OR format_contract NOT IN ('mtt-v1','seat-first-satellite-v1','sng-v1','spin-v1'))) THEN\n    RAISE EXCEPTION 'MTT_ACTIVATION_ACTIVE_FORMAT_UNQUALIFIED' USING ERRCODE='55000';\n   END IF;\n   RETURN NEW;\n  END IF;\n END IF;\n RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_IMMUTABLE' USING ERRCODE='55000';\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_guard_mtt_admission_contract","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=pg_catalog, public"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_lock_mtt_admission_contract()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_lock_mtt_admission_contract()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE v_abi text;\nBEGIN\n  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;\n  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN\n    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';\n  END IF;\n  RETURN v_abi;\nEND $function$\n","metadata":{"oid":"35049258","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE v_abi text;\nBEGIN\n  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;\n  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN\n    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';\n  END IF;\n  RETURN v_abi;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_lock_mtt_admission_contract","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=pg_catalog, public"],"proretset":false,"prosecdef":true,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_read_mtt_admission_contract()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_read_mtt_admission_contract()\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE v_abi text;\nBEGIN\n SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton;\n IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN\n  RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';\n END IF;\n RETURN v_abi;\nEND $function$\n","metadata":{"oid":"35059402","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE v_abi text;\nBEGIN\n SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton;\n IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN\n  RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';\n END IF;\n RETURN v_abi;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_read_mtt_admission_contract","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=pg_catalog, public"],"proretset":false,"prosecdef":true,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_poker_reject_diamond_chip_money()","definition":"CREATE OR REPLACE FUNCTION public.fn_poker_reject_diamond_chip_money()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_row jsonb := to_jsonb(NEW);\nBEGIN\n  /* DIAMOND PHASE 9, STEP 0 (2026-09-29). Ruling 16: no unions, agents,\n     commissions, chip wallets or chip ledgers in the Diamond Arena. A row of\n     a chip money table that belongs to the arena - by its club, by the table\n     it was played at, or by the event it was paid into - is refused by name,\n     as poker_arena_no_hierarchy refuses an agent row. */\n  IF EXISTS (SELECT 1 FROM public.clubs c\n              WHERE c.id = (v_row->>'club_id')::uuid AND c.asset = 'diamonds')\n     OR EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id = t.club_id\n                 WHERE t.id = (v_row->>'table_id')::uuid AND c.asset = 'diamonds')\n     OR EXISTS (SELECT 1 FROM public.tournaments e JOIN public.clubs c ON c.id = e.club_id\n                 WHERE e.id IN ((v_row->>'tournament_id')::uuid,\n                                (v_row->>'source_tournament_id')::uuid,\n                                (v_row->>'source_satellite_id')::uuid)\n                   AND c.asset = 'diamonds') THEN\n    RAISE EXCEPTION 'Diamond Arena Has No Chip Money' USING ERRCODE = '23514',\n      DETAIL = format('public.%I refuses a row that belongs to the Diamond Arena.', TG_TABLE_NAME);\n  END IF;\n  RETURN NEW;\nEND $function$\n","metadata":{"oid":"71854111","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nDECLARE\n  v_row jsonb := to_jsonb(NEW);\nBEGIN\n  /* DIAMOND PHASE 9, STEP 0 (2026-09-29). Ruling 16: no unions, agents,\n     commissions, chip wallets or chip ledgers in the Diamond Arena. A row of\n     a chip money table that belongs to the arena - by its club, by the table\n     it was played at, or by the event it was paid into - is refused by name,\n     as poker_arena_no_hierarchy refuses an agent row. */\n  IF EXISTS (SELECT 1 FROM public.clubs c\n              WHERE c.id = (v_row->>'club_id')::uuid AND c.asset = 'diamonds')\n     OR EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id = t.club_id\n                 WHERE t.id = (v_row->>'table_id')::uuid AND c.asset = 'diamonds')\n     OR EXISTS (SELECT 1 FROM public.tournaments e JOIN public.clubs c ON c.id = e.club_id\n                 WHERE e.id IN ((v_row->>'tournament_id')::uuid,\n                                (v_row->>'source_tournament_id')::uuid,\n                                (v_row->>'source_satellite_id')::uuid)\n                   AND c.asset = 'diamonds') THEN\n    RAISE EXCEPTION 'Diamond Arena Has No Chip Money' USING ERRCODE = '23514',\n      DETAIL = format('public.%I refuses a row that belongs to the Diamond Arena.', TG_TABLE_NAME);\n  END IF;\n  RETURN NEW;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_poker_reject_diamond_chip_money","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_ca_reject_diamond_chip_rake_row()","definition":"CREATE OR REPLACE FUNCTION public.fn_ca_reject_diamond_chip_rake_row()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  IF EXISTS (SELECT 1 FROM public.clubs WHERE id=NEW.club_id AND asset='diamonds') THEN\n    RAISE EXCEPTION 'Diamond Rake Is Never A Chip Rake Record' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND $function$\n","metadata":{"oid":"110826622","proacl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"probin":null,"prosrc":"\nBEGIN\n  IF EXISTS (SELECT 1 FROM public.clubs WHERE id=NEW.club_id AND asset='diamonds') THEN\n    RAISE EXCEPTION 'Diamond Rake Is Never A Chip Rake Record' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"fn_ca_reject_diamond_chip_rake_row","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":false,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"smarter_private.original_inventory_source_ref_md5(jsonb)","definition":"CREATE OR REPLACE FUNCTION smarter_private.original_inventory_source_ref_md5(ref jsonb)\n RETURNS text\n LANGUAGE plpgsql\n STABLE\n SET search_path TO 'pg_catalog', 'public', 'smarter_private'\n SET \"TimeZone\" TO 'UTC'\nAS $function$\nDECLARE n integer;digest text;k text;v_ref_id uuid;v_ref_other uuid;sid bigint;economic jsonb;s record;d record;a record;\nBEGIN\n IF ref IS NULL OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'kind' IS NULL THEN RETURN NULL;END IF;\n k:=ref->>'kind';\n IF k='inventory_event' THEN\n  sid:=(ref->>'id')::bigint;SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.union_pnl_inventory_events t WHERE t.event_id=sid;\n ELSIF k='migration_source' THEN\n  SELECT count(*),min(md5(array_to_string(t.statements,E'\\n'))) INTO n,digest FROM supabase_migrations.schema_migrations t\n  WHERE t.version=ref->>'id' AND cardinality(t.statements)=1;\n ELSIF k='mint_ledger' THEN\n  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.ca_mint_ledger t WHERE t.op_id=ref->>'id';\n ELSIF k='wallet_credit_idempotency' THEN\n  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_credit_idempotency t WHERE t.key=ref->>'id';\n ELSE\n  v_ref_id:=(ref->>'id')::uuid;\n  CASE k\n  WHEN 'chip_ledger' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_ledger t WHERE t.id=v_ref_id;\n  WHEN 'chip_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_transactions t WHERE t.id=v_ref_id;\n  WHEN 'cash_move' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_moves t WHERE t.id=v_ref_id;\n  WHEN 'wallet_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_transactions t WHERE t.id=v_ref_id;\n  WHEN 'cash_manifest' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_hand_participant_manifests t WHERE t.id=v_ref_id;\n  WHEN 'cash_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_funding_receipts t WHERE t.id=v_ref_id;\n  WHEN 'tournament_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_participant_funding_receipts t WHERE t.id=v_ref_id;\n  WHEN 'original_hand_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_qualification t WHERE t.submission_id=v_ref_id;\n  WHEN 'original_hand_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_restorations t WHERE t.submission_id=v_ref_id;\n  WHEN 'cash_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_qualification t WHERE t.submission_id=v_ref_id;\n  WHEN 'cash_custody' THEN\n   v_ref_other:=(ref->>'other_id')::uuid;\n   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_custody t WHERE t.submission_id=v_ref_id AND t.user_id=v_ref_other;\n  WHEN 'undealt_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_qualification t WHERE t.tournament_id=v_ref_id;\n  WHEN 'undealt_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_restorations t WHERE t.tournament_id=v_ref_id;\n  WHEN 'terminal_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_terminal_settlements t WHERE t.tournament_id=v_ref_id;\n  WHEN 'cancellation_receipt' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_cancellation_receipts t WHERE t.tournament_id=v_ref_id;\n  WHEN 'tournament_payout' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_payouts t WHERE t.id=v_ref_id;\n  WHEN 'tournament_credit' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_accounting_credit_receipts t WHERE t.id=v_ref_id;\n  WHEN 'satellite_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_settlements t WHERE t.tournament_id=v_ref_id;\n  WHEN 'satellite_award' THEN\n   v_ref_other:=(ref->>'other_id')::uuid;\n   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_awards t WHERE t.tournament_id=v_ref_id AND t.user_id=v_ref_other;\n  WHEN 'tournament_ticket' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_tickets t WHERE t.id=v_ref_id;\n  WHEN 'atomic_economics' THEN\n   SELECT count(*),min(md5(jsonb_build_object('hand_id',t.hand_id,'table_id',t.table_id,'hand_number',t.hand_number,\n    'payload_hash',t.payload_hash,'stack_result',t.stack_result,'committed_at',t.committed_at,\n    'post_commit_completed_at',t.post_commit_completed_at,'post_commit_result',t.post_commit_result)::text)) INTO n,digest\n   FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id;\n   IF n=0 THEN\n    -- RETENTION PRUNED THIS COMMIT (2026-10-14). sp_prune_hand_history deletes a\n    -- settled horse hand's atomic commit after the retention window and, in the\n    -- same transaction, writes its disposal from the live row. The digest below was\n    -- certified while the row existed; the disposal is the only authority that the\n    -- hand settled and was removed by retention. Anything else stays refused.\n    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;\n    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;\n    SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id AND t.table_id=d.table_id AND t.hand_number=d.hand_number;\n    IF NOT FOUND\n    OR EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=d.table_id AND x.hand_number=d.hand_number)\n    OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)\n    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'\n    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'\n    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text\n    OR d.expected->>'table_id' IS DISTINCT FROM d.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM d.hand_number::text\n    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash\n    OR (d.expected->>'settlement_completed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'settlement_completed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()\n    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'settlement_completed_at')::timestamptz+interval '8 days'\n    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8\n    OR ref->>'md5' IS NULL OR ref->>'md5' !~ '^[0-9a-f]{32}$' THEN RETURN NULL;END IF;\n    n:=1;digest:=ref->>'md5';\n   END IF;\n  WHEN 'signed_economics' THEN\n   SELECT count(*) INTO n FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;\n   IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n   SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;\n   IF NOT FOUND THEN RETURN NULL;END IF;\n   IF s.request<>'{}'::jsonb THEN\n    economic:=jsonb_build_object('submission_id',s.submission_id,'request_hash',s.request_hash,'table_id',s.table_id,\n     'hand_number',s.hand_number,'lease_generation',s.lease_generation,'stacks',s.request->'p_stacks','started_at',s.request#>>'{p_hand_row,started_at}');\n   ELSE\n    -- Reconstruct only the captured card-free economic DTO under the existing\n    -- qualified retention disposal. Missing payload alone is never authority.\n    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF NOT FOUND THEN RETURN NULL;END IF;\n    SELECT * INTO a FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF NOT FOUND THEN\n     -- RETENTION PRUNED THIS COMMIT (2026-10-14): its settled completion is read from\n     -- the disposal retention wrote from the live row in the same transaction.\n     IF EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=s.table_id AND x.hand_number=s.hand_number)\n     OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)\n     OR NOT pg_input_is_valid(d.expected->>'settlement_completed_at','timestamptz') THEN RETURN NULL;END IF;\n     a.post_commit_completed_at:=(d.expected->>'settlement_completed_at')::timestamptz;\n     a.committed_at:=a.post_commit_completed_at;\n     a.post_commit_result:=jsonb_build_object('ok',true);\n    END IF;\n    IF s.retained_at IS NULL OR NOT isfinite(s.retained_at)\n    OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'\n    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'\n    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'\n    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text\n    OR d.expected->>'table_id' IS DISTINCT FROM s.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM s.hand_number::text\n    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash\n    OR (d.expected->>'settlement_completed_at')::timestamptz IS DISTINCT FROM a.post_commit_completed_at\n    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()\n    OR (d.expected->>'hand_created_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'hand_created_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'hand_created_at')::timestamptz+interval '8 days'\n    OR (d.expected->>'disposed_at')::timestamptz < a.post_commit_completed_at+interval '8 days'\n    OR (d.expected->>'disposed_at')::timestamptz < s.retained_at+interval '8 days'\n    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8\n    THEN RETURN NULL;END IF;\n    economic:=ref->'economic';\n    IF jsonb_typeof(economic) IS DISTINCT FROM 'object' OR economic->>'submission_id' IS DISTINCT FROM v_ref_id::text\n    OR economic->>'request_hash' IS DISTINCT FROM s.request_hash OR economic->>'table_id' IS DISTINCT FROM s.table_id::text\n    OR economic->>'hand_number' IS DISTINCT FROM s.hand_number::text OR economic->>'lease_generation' IS DISTINCT FROM s.lease_generation::text\n    OR jsonb_typeof(economic->'stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(economic->'stacks')=0\n    OR economic->>'started_at' IS NULL OR NOT isfinite((economic->>'started_at')::timestamptz)\n    OR (economic->>'started_at')::timestamptz>a.committed_at THEN RETURN NULL;END IF;\n   END IF;\n   n:=1;digest:=md5(economic::text);\n  ELSE RETURN NULL;\n  END CASE;\n END IF;\n IF n IS DISTINCT FROM 1 OR digest IS NULL THEN RETURN NULL;END IF;\n RETURN digest;\nEXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN NULL;\nEND $function$\n","metadata":{"oid":"155813233","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE n integer;digest text;k text;v_ref_id uuid;v_ref_other uuid;sid bigint;economic jsonb;s record;d record;a record;\nBEGIN\n IF ref IS NULL OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'kind' IS NULL THEN RETURN NULL;END IF;\n k:=ref->>'kind';\n IF k='inventory_event' THEN\n  sid:=(ref->>'id')::bigint;SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.union_pnl_inventory_events t WHERE t.event_id=sid;\n ELSIF k='migration_source' THEN\n  SELECT count(*),min(md5(array_to_string(t.statements,E'\\n'))) INTO n,digest FROM supabase_migrations.schema_migrations t\n  WHERE t.version=ref->>'id' AND cardinality(t.statements)=1;\n ELSIF k='mint_ledger' THEN\n  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.ca_mint_ledger t WHERE t.op_id=ref->>'id';\n ELSIF k='wallet_credit_idempotency' THEN\n  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_credit_idempotency t WHERE t.key=ref->>'id';\n ELSE\n  v_ref_id:=(ref->>'id')::uuid;\n  CASE k\n  WHEN 'chip_ledger' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_ledger t WHERE t.id=v_ref_id;\n  WHEN 'chip_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_transactions t WHERE t.id=v_ref_id;\n  WHEN 'cash_move' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_moves t WHERE t.id=v_ref_id;\n  WHEN 'wallet_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_transactions t WHERE t.id=v_ref_id;\n  WHEN 'cash_manifest' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_hand_participant_manifests t WHERE t.id=v_ref_id;\n  WHEN 'cash_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_funding_receipts t WHERE t.id=v_ref_id;\n  WHEN 'tournament_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_participant_funding_receipts t WHERE t.id=v_ref_id;\n  WHEN 'original_hand_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_qualification t WHERE t.submission_id=v_ref_id;\n  WHEN 'original_hand_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_restorations t WHERE t.submission_id=v_ref_id;\n  WHEN 'cash_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_qualification t WHERE t.submission_id=v_ref_id;\n  WHEN 'cash_custody' THEN\n   v_ref_other:=(ref->>'other_id')::uuid;\n   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_custody t WHERE t.submission_id=v_ref_id AND t.user_id=v_ref_other;\n  WHEN 'undealt_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_qualification t WHERE t.tournament_id=v_ref_id;\n  WHEN 'undealt_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_restorations t WHERE t.tournament_id=v_ref_id;\n  WHEN 'terminal_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_terminal_settlements t WHERE t.tournament_id=v_ref_id;\n  WHEN 'cancellation_receipt' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_cancellation_receipts t WHERE t.tournament_id=v_ref_id;\n  WHEN 'tournament_payout' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_payouts t WHERE t.id=v_ref_id;\n  WHEN 'tournament_credit' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_accounting_credit_receipts t WHERE t.id=v_ref_id;\n  WHEN 'satellite_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_settlements t WHERE t.tournament_id=v_ref_id;\n  WHEN 'satellite_award' THEN\n   v_ref_other:=(ref->>'other_id')::uuid;\n   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_awards t WHERE t.tournament_id=v_ref_id AND t.user_id=v_ref_other;\n  WHEN 'tournament_ticket' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_tickets t WHERE t.id=v_ref_id;\n  WHEN 'atomic_economics' THEN\n   SELECT count(*),min(md5(jsonb_build_object('hand_id',t.hand_id,'table_id',t.table_id,'hand_number',t.hand_number,\n    'payload_hash',t.payload_hash,'stack_result',t.stack_result,'committed_at',t.committed_at,\n    'post_commit_completed_at',t.post_commit_completed_at,'post_commit_result',t.post_commit_result)::text)) INTO n,digest\n   FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id;\n   IF n=0 THEN\n    -- RETENTION PRUNED THIS COMMIT (2026-10-14). sp_prune_hand_history deletes a\n    -- settled horse hand's atomic commit after the retention window and, in the\n    -- same transaction, writes its disposal from the live row. The digest below was\n    -- certified while the row existed; the disposal is the only authority that the\n    -- hand settled and was removed by retention. Anything else stays refused.\n    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;\n    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;\n    SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id AND t.table_id=d.table_id AND t.hand_number=d.hand_number;\n    IF NOT FOUND\n    OR EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=d.table_id AND x.hand_number=d.hand_number)\n    OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)\n    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'\n    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'\n    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text\n    OR d.expected->>'table_id' IS DISTINCT FROM d.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM d.hand_number::text\n    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash\n    OR (d.expected->>'settlement_completed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'settlement_completed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()\n    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'settlement_completed_at')::timestamptz+interval '8 days'\n    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8\n    OR ref->>'md5' IS NULL OR ref->>'md5' !~ '^[0-9a-f]{32}$' THEN RETURN NULL;END IF;\n    n:=1;digest:=ref->>'md5';\n   END IF;\n  WHEN 'signed_economics' THEN\n   SELECT count(*) INTO n FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;\n   IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n   SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;\n   IF NOT FOUND THEN RETURN NULL;END IF;\n   IF s.request<>'{}'::jsonb THEN\n    economic:=jsonb_build_object('submission_id',s.submission_id,'request_hash',s.request_hash,'table_id',s.table_id,\n     'hand_number',s.hand_number,'lease_generation',s.lease_generation,'stacks',s.request->'p_stacks','started_at',s.request#>>'{p_hand_row,started_at}');\n   ELSE\n    -- Reconstruct only the captured card-free economic DTO under the existing\n    -- qualified retention disposal. Missing payload alone is never authority.\n    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;\n    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF NOT FOUND THEN RETURN NULL;END IF;\n    SELECT * INTO a FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;\n    IF NOT FOUND THEN\n     -- RETENTION PRUNED THIS COMMIT (2026-10-14): its settled completion is read from\n     -- the disposal retention wrote from the live row in the same transaction.\n     IF EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=s.table_id AND x.hand_number=s.hand_number)\n     OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)\n     OR NOT pg_input_is_valid(d.expected->>'settlement_completed_at','timestamptz') THEN RETURN NULL;END IF;\n     a.post_commit_completed_at:=(d.expected->>'settlement_completed_at')::timestamptz;\n     a.committed_at:=a.post_commit_completed_at;\n     a.post_commit_result:=jsonb_build_object('ok',true);\n    END IF;\n    IF s.retained_at IS NULL OR NOT isfinite(s.retained_at)\n    OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'\n    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'\n    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'\n    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text\n    OR d.expected->>'table_id' IS DISTINCT FROM s.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM s.hand_number::text\n    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash\n    OR (d.expected->>'settlement_completed_at')::timestamptz IS DISTINCT FROM a.post_commit_completed_at\n    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()\n    OR (d.expected->>'hand_created_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'hand_created_at')::timestamptz)\n    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'hand_created_at')::timestamptz+interval '8 days'\n    OR (d.expected->>'disposed_at')::timestamptz < a.post_commit_completed_at+interval '8 days'\n    OR (d.expected->>'disposed_at')::timestamptz < s.retained_at+interval '8 days'\n    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8\n    THEN RETURN NULL;END IF;\n    economic:=ref->'economic';\n    IF jsonb_typeof(economic) IS DISTINCT FROM 'object' OR economic->>'submission_id' IS DISTINCT FROM v_ref_id::text\n    OR economic->>'request_hash' IS DISTINCT FROM s.request_hash OR economic->>'table_id' IS DISTINCT FROM s.table_id::text\n    OR economic->>'hand_number' IS DISTINCT FROM s.hand_number::text OR economic->>'lease_generation' IS DISTINCT FROM s.lease_generation::text\n    OR jsonb_typeof(economic->'stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(economic->'stacks')=0\n    OR economic->>'started_at' IS NULL OR NOT isfinite((economic->>'started_at')::timestamptz)\n    OR (economic->>'started_at')::timestamptz>a.committed_at THEN RETURN NULL;END IF;\n   END IF;\n   n:=1;digest:=md5(economic::text);\n  ELSE RETURN NULL;\n  END CASE;\n END IF;\n IF n IS DISTINCT FROM 1 OR digest IS NULL THEN RETURN NULL;END IF;\n RETURN digest;\nEXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN NULL;\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"original_inventory_source_ref_md5","prorows":0,"pronargs":1,"proowner":"16384","proconfig":["search_path=pg_catalog, public, smarter_private","TimeZone=UTC"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["ref"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"24465641","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"smarter_private.original_inventory_basis_generation()","definition":"CREATE OR REPLACE FUNCTION smarter_private.original_inventory_basis_generation()\n RETURNS text\n LANGUAGE plpgsql\n STABLE\n SET search_path TO 'pg_catalog', 'public', 'smarter_private'\n SET \"TimeZone\" TO 'UTC'\nAS $function$\nDECLARE r jsonb; receipt jsonb; c record; proofs text;source_hash text;source_count bigint;discharges jsonb:='[]';treasury text;tw record;tp jsonb;\nBEGIN\n IF (SELECT count(*) FROM smarter_private.original_inventory_restoration_cases) IS DISTINCT FROM 245::bigint\n OR (SELECT count(*) FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z') IS DISTINCT FROM 245::bigint\n OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN NULL;END IF;\n -- Deduplicate shared original authorities; no 4x family source scan.\n FOR r IN SELECT DISTINCT x FROM smarter_private.original_inventory_restoration_cases k CROSS JOIN LATERAL jsonb_array_elements(k.source_refs)x LOOP\n IF r->>'md5' IS NULL OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;\n END LOOP;\n FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' ORDER BY event_id LOOP\n receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,md5((c.original_witness-'original_table_scope'-'original_manifest_scope')::text));\n IF receipt->>'status' NOT IN('pending','discharged') OR receipt->>'status' IS NULL THEN RETURN NULL;END IF;\n discharges:=discharges||jsonb_build_array(jsonb_build_object('event_id',c.event_id,'receipt',receipt));\n END LOOP;\n SELECT md5(string_agg(event_id::text||':'||witness_md5||':'||proof_md5,'|' ORDER BY event_id)) INTO proofs\n FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z';\n SELECT count(to_regprocedure(signature)),md5(string_agg(signature||':'||md5(pg_get_functiondef(to_regprocedure(signature))),'|' ORDER BY signature)) INTO source_count,source_hash FROM(VALUES ('public.fn_union_pnl_boundary(uuid,timestamptz)'),('public.fn_union_pnl_original_flow_evidence(uuid,timestamptz,timestamptz)'),('public.fn_union_pnl_evidence_report(uuid,timestamptz,timestamptz)'),('smarter_private.original_inventory_basis_generation()'),('smarter_private.original_inventory_proof_sources_match()'))s(signature);\n IF source_count IS DISTINCT FROM 5::bigint OR source_hash IS NULL OR proofs IS NULL THEN RETURN NULL;END IF;\n -- A newly admitted original treasury witness is a new proof input. Old\n -- derived blocked parts must be recomputed by their existing generation owner.\n FOR tw IN SELECT ledger_id,kind FROM smarter_private.original_treasury_historical_admissions ORDER BY ledger_id LOOP\n  tp:=CASE tw.kind WHEN 'gift' THEN smarter_private.original_treasury_gift_evidence(tw.ledger_id)\n   WHEN 'return' THEN smarter_private.original_treasury_return_evidence(tw.ledger_id) END;\n  IF tp->>'status' IS DISTINCT FROM 'proven' THEN RETURN NULL;END IF;\n END LOOP;\n SELECT md5(COALESCE(string_agg(ledger_id::text||':'||kind||':'||source_fingerprint,'|' ORDER BY ledger_id),'no-original-treasury-witnesses')) INTO treasury\n FROM smarter_private.original_treasury_historical_admissions;\n RETURN 'original-inventory-245-v1:'||md5(source_hash||'|'||proofs||'|'||discharges::text||'|'||treasury);\nEND $function$\n","metadata":{"oid":"155814144","proacl":["postgres=X/postgres"],"probin":null,"prosrc":"\nDECLARE r jsonb; receipt jsonb; c record; proofs text;source_hash text;source_count bigint;discharges jsonb:='[]';treasury text;tw record;tp jsonb;\nBEGIN\n IF (SELECT count(*) FROM smarter_private.original_inventory_restoration_cases) IS DISTINCT FROM 245::bigint\n OR (SELECT count(*) FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z') IS DISTINCT FROM 245::bigint\n OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN NULL;END IF;\n -- Deduplicate shared original authorities; no 4x family source scan.\n FOR r IN SELECT DISTINCT x FROM smarter_private.original_inventory_restoration_cases k CROSS JOIN LATERAL jsonb_array_elements(k.source_refs)x LOOP\n IF r->>'md5' IS NULL OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;\n END LOOP;\n FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' ORDER BY event_id LOOP\n receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,md5((c.original_witness-'original_table_scope'-'original_manifest_scope')::text));\n IF receipt->>'status' NOT IN('pending','discharged') OR receipt->>'status' IS NULL THEN RETURN NULL;END IF;\n discharges:=discharges||jsonb_build_array(jsonb_build_object('event_id',c.event_id,'receipt',receipt));\n END LOOP;\n SELECT md5(string_agg(event_id::text||':'||witness_md5||':'||proof_md5,'|' ORDER BY event_id)) INTO proofs\n FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z';\n SELECT count(to_regprocedure(signature)),md5(string_agg(signature||':'||md5(pg_get_functiondef(to_regprocedure(signature))),'|' ORDER BY signature)) INTO source_count,source_hash FROM(VALUES ('public.fn_union_pnl_boundary(uuid,timestamptz)'),('public.fn_union_pnl_original_flow_evidence(uuid,timestamptz,timestamptz)'),('public.fn_union_pnl_evidence_report(uuid,timestamptz,timestamptz)'),('smarter_private.original_inventory_basis_generation()'),('smarter_private.original_inventory_proof_sources_match()'))s(signature);\n IF source_count IS DISTINCT FROM 5::bigint OR source_hash IS NULL OR proofs IS NULL THEN RETURN NULL;END IF;\n -- A newly admitted original treasury witness is a new proof input. Old\n -- derived blocked parts must be recomputed by their existing generation owner.\n FOR tw IN SELECT ledger_id,kind FROM smarter_private.original_treasury_historical_admissions ORDER BY ledger_id LOOP\n  tp:=CASE tw.kind WHEN 'gift' THEN smarter_private.original_treasury_gift_evidence(tw.ledger_id)\n   WHEN 'return' THEN smarter_private.original_treasury_return_evidence(tw.ledger_id) END;\n  IF tp->>'status' IS DISTINCT FROM 'proven' THEN RETURN NULL;END IF;\n END LOOP;\n SELECT md5(COALESCE(string_agg(ledger_id::text||':'||kind||':'||source_fingerprint,'|' ORDER BY ledger_id),'no-original-treasury-witnesses')) INTO treasury\n FROM smarter_private.original_treasury_historical_admissions;\n RETURN 'original-inventory-245-v1:'||md5(source_hash||'|'||proofs||'|'||discharges::text||'|'||treasury);\nEND ","procost":100,"prokind":"f","prolang":"13573","proname":"original_inventory_basis_generation","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=pg_catalog, public, smarter_private","TimeZone=UTC"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"24465641","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"smarter_private.original_inventory_proof_sources_match()","definition":"CREATE OR REPLACE FUNCTION smarter_private.original_inventory_proof_sources_match()\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO 'pg_catalog'\nAS $function$\n SELECT count(*)=65 AND bool_and(p.oid IS NOT NULL AND p.proowner='postgres'::regrole AND md5(pg_get_functiondef(p.oid)) IS NOT DISTINCT FROM x.body_md5)\n FROM(VALUES ('public.fn_union_pnl_inventory_state(timestamptz,timestamptz)','d77f5ad055ee433875efed7fd53bd25a'),('public.fn_union_pnl_inventory_population(timestamptz,timestamptz)','449f6f13feefe0d7e26e767a3465bc67'),('public.fn_union_pnl_inventory_as_of(timestamptz)','85513ff85d2b37ad04b79f89e125f1aa'),('smarter_private.original_retirement_boundary_proof(jsonb,timestamptz,timestamptz)','56457798f46f7c06a32b0e52915740a0'),('smarter_private.original_paired_seat_restoration_proof(jsonb,jsonb,timestamptz,timestamptz)','ada80c7f667ca7dad36cf223c80c3a6a'),('smarter_private.original_closed_tournament_rails_proof(jsonb,timestamptz)','a9319182a566e9917353765c414a1aa1'),('smarter_private.original_closed_player_proof(jsonb,timestamptz,timestamptz)','a441c3abe887cc4528268e347916d236'),('smarter_private.original_continued_chair_proof(jsonb,timestamptz,timestamptz)','8876018a8370a99f4012696cb264c740'),('smarter_private.original_returned_cash_base_proof(jsonb,timestamptz,timestamptz)','7ed06b